insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tiramisu', 'Tiramisu', array['tiramisu maison', 'tiramisu cafe']::text[], 'dish', $r$[{"title":"Tiramisu","intro":"Des biscuits imbibés de café, une crème au mascarpone et un voile de cacao.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"tiramisu","veg":true,"oven":false,"cold":false,"missing":"","origin":"Dessert italien","serves":4,"items":[{"name":"mascarpone","plural":"mascarpone","qty":250,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"biscuit à la cuillère","plural":"biscuits à la cuillère","qty":20,"unit":"","have":false},{"name":"café fort","plural":"café fort","qty":30,"unit":"cl","have":false},{"name":"cacao en poudre","plural":"cacao en poudre","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fouette les jaunes avec le sucre, puis ajoute le mascarpone.","timer":null},{"text":"Monte les blancs en neige et incorpore-les.","timer":null},{"text":"Trempe rapidement les biscuits dans le café froid et tapisse-en un plat.","timer":null},{"text":"Alterne crème et biscuits, termine par la crème.","timer":null},{"text":"Mets au frais 6 h, puis saupoudre de cacao.","timer":{"label":"Frais","min":360}}],"dessert":true,"variant":"La classique","change":""},{"title":"Tiramisu aux fraises","intro":"Le tiramisu de printemps, aux fraises.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"strawberry tiramisu","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"mascarpone","plural":"mascarpone","qty":250,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"biscuit à la cuillère","plural":"biscuits à la cuillère","qty":20,"unit":"","have":false},{"name":"fraise","plural":"fraises","qty"