insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('creme brulee', 'Crème brûlée', array[]::text[], 'dish', $r$[{"title":"Crème brûlée","intro":"Une crème vanillée onctueuse sous une fine couche de sucre caramélisé.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"creme brulee","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"crème fraîche liquide","plural":"crèmes fraîche liquide","qty":50,"unit":"cl","have":false},{"name":"jaune d'œuf","plural":"jaunes d'œufs","qty":5,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"gousse de vanille","plural":"gousses de vanille","qty":1,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 100 °C.","timer":null},{"text":"Fais chauffer la crème avec la vanille fendue.","timer":null},{"text":"Fouette les jaunes et le sucre, puis verse la crème chaude en remuant.","timer":null},{"text":"Répartis dans des ramequins et enfourne 1 h.","timer":{"label":"Four","min":60}},{"text":"Laisse refroidir au frais 3 h, saupoudre de sucre roux et caramélise au chalumeau ou sous le gril.","timer":{"label":"Frais","min":180}}],"dessert":true,"variant":"La classique","change":""},{"title":"Crème brûlée au café","intro":"La crème brûlée, au café.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"coffee creme brulee","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"crème fraîche liquide","plural":"crèmes fraîche liquide","qty":50,"unit":"cl","have":false},{"name":"jaune d'œuf","plural":"jaunes d'œufs","qty":5,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"café soluble","plural":"café soluble","qty":2,"unit":"c. à c.","have":false},{"name":"sucre roux","plural":"sucre roux","qty":4,"unit":"c. à s.","have":false}],