insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('flan patissier', 'Flan pâtissier', array['flan', 'flan patissier maison']::text[], 'dish', $r$[{"title":"Flan pâtissier","intro":"Le flan de boulangerie : une crème vanillée ferme sur une pâte croustillante.","minutes":80,"calories":340,"difficulty":"Moyen","imageSearch":"french custard flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"lait entier","plural":"lait entier","qty":750,"unit":"ml","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":150,"unit":"g","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":70,"unit":"g","have":false},{"name":"gousse de vanille","plural":"gousses de vanille","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Étale la pâte dans un moule haut.","timer":null},{"text":"Fais chauffer le lait avec la vanille.","timer":null},{"text":"Fouette les œufs, le sucre et la fécule, verse le lait chaud et remets sur le feu en remuant jusqu'à épaississement.","timer":{"label":"Crème","min":4}},{"text":"Verse sur la pâte et enfourne 45 min.","timer":{"label":"Four","min":45}},{"text":"Laisse refroidir puis 4 h au frais.","timer":{"label":"Frais","min":240}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Flan sans pâte","intro":"Le flan crémeux, cuit directement dans le plat.","minutes":60,"calories":240,"difficulty":"Facile","imageSearch":"crustless custard flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lait","plural":"laits","qty":750,"unit":"ml","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":60,"unit":"g","have":false},{"name":"sucre vanillé","plural":"sucres vanillés","qty":2,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Prépare la crème épaisse comme pour le flan pâtissier.","timer":null},{"text":"Verse dans un plat beurré et enfourne 40 min.","timer":{"label":"Four","min":40}},{"text":"Laisse refroidir puis au frais.","timer":{"label":"Frais","min":180}}],"dessert":true,"variant":"Sans pâte","change":"Sans pâte, plus léger."},{"title":"Flan coco","intro":"Un flan coco, comme aux Antilles.","minutes":60,"calories":360,"difficulty":"Facile","imageSearch":"coconut flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"lait de coco","plural":"lait de coco","qty":25,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"noix de coco râpée","plural":"noix de coco râpée","qty":60,"unit":"g","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":60,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais chauffer les laits, ajoute les œufs battus avec le sucre et la fécule, et fais épaissir.","timer":{"label":"Crème","min":4}},{"text":"Ajoute la noix de coco, verse dans un plat et enfourne 40 min.","timer":{"label":"Four","min":40}}],"dessert":true,"variant":"À la noix de coco","change":"De la noix de coco et du lait de coco parfument le flan."}]$r$::jsonb, 'claude')
