insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('dos de cabillaud', 'Dos de cabillaud', array['cabillaud au four', 'filet de cabillaud']::text[], 'dish', $r$[{"title":"Dos de cabillaud au four, beurre citronné","intro":"Un cabillaud nacré, cuit au four avec un beurre au citron et au persil.","minutes":25,"calories":320,"difficulty":"Facile","imageSearch":"baked cod lemon butter","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dos de cabillaud","plural":"dos de cabillaud","qty":4,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Pose le cabillaud dans un plat, sale et poivre.","timer":null},{"text":"Fais fondre le beurre avec l'ail, le jus du citron et le persil, et verse sur le poisson.","timer":null},{"text":"Enfourne 12 min.","timer":{"label":"Four","min":12}}],"variant":"La classique","change":""},{"title":"Cabillaud à la provençale","intro":"Un cabillaud ensoleillé, à la tomate, aux olives et au thym.","minutes":30,"calories":300,"difficulty":"Facile","imageSearch":"cod provencal tomato olives","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dos de cabillaud","plural":"dos de cabillaud","qty":4,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"olive noire","plural":"olives noires","qty":50,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":