insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('filet mignon de porc', 'Filet mignon de porc', array['filet mignon', 'filet mignon a la moutarde', 'filet mignon en croute']::text[], 'dish', $r$[{"title":"Filet mignon à la moutarde","intro":"Un filet mignon tendre en médaillons, dans une sauce crème-moutarde.","minutes":30,"calories":480,"difficulty":"Facile","imageSearch":"pork tenderloin mustard sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":2,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":2,"unit":"c. à s.","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le filet en médaillons épais et fais-les dorer dans le beurre 3 min de chaque côté.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute les échalotes, puis le vin, et laisse réduire 2 min.","timer":{"label":"Cuisson","min":2}},{"text":"Ajoute la crème et la moutarde, couvre et cuis 8 min.","timer":{"label":"Cuisson","min":8}}],"variant":"La classique","change":""},{"title":"Filet mignon au miel et au romarin","intro":"Un filet mignon laqué au miel, juteux et parfumé.","minutes":40,"calories":460,"difficulty":"Facile","imageSearch":"honey roasted pork tenderloin","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":2,"unit":"","have":false},{"name":"miel","plural":"miel","qty":2,"unit":"c. à s.","have":false},{"name":"romarin","plural":"romarin","qty":null,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Fais dorer les filets entiers dans l'huile sur toutes les faces.","timer":null},{"text":"Badigeonne-les de miel, ajoute l'ail et le romarin, sale et poivre.","timer":null},{"text":"Enfourne 20 min, puis laisse reposer 5 min avant de trancher.","timer":{"label":"Four","min":20}}],"variant":"Miel et romarin","change":"Rôti entier au four, laqué au miel."},{"title":"Filet mignon aux champignons","intro":"Le filet mignon en sauce crémeuse aux champignons.","minutes":30,"calories":480,"difficulty":"Facile","imageSearch":"pork tenderloin mushroom sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":2,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer les médaillons dans le beurre 3 min de chaque côté. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir l'échalote et les champignons 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute la crème et la viande, et laisse mijoter 6 min.","timer":{"label":"Mijotage","min":6}}],"variant":"Aux champignons","change":"Une sauce aux cham