insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('cordon bleu', 'Cordon bleu', array['cordon bleu maison']::text[], 'dish', $r$[{"title":"Cordon bleu maison","intro":"Une escalope de dinde farcie au jambon et au fromage, panée et dorée.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"homemade cordon bleu","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"escalope de dinde","plural":"escalopes de dinde","qty":4,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental","plural":"emmental","qty":4,"unit":"tranches","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"farine","plural":"farines","qty":4,"unit":"c. à s.","have":false},{"name":"chapelure","plural":"chapelure","qty":100,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Aplatis les escalopes et coupe-les en deux dans l'épaisseur sans les séparer.","timer":null},{"text":"Garnis de jambon et d'emmental, puis referme.","timer":null},{"text":"Passe-les dans la farine, l'œuf battu puis la chapelure.","timer":null},{"text":"Fais-les dorer dans l'huile 5 min de chaque côté.","timer":{"label":"Poêle","min":10}}],"kids":true,"variant":"La classique","change":""},{"title":"Cordon bleu au four","intro":"Les cordons bleus plus légers, cuits au four.","minutes":35,"calories":440,"difficulty":"Facile","imageSearch":"baked cordon bleu","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"escalope de dinde","plural":"escalopes de dinde","qty":4,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental","plural":"emmental","qty":4,"unit":"tranches","have":false},{"name":"œuf"