insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('petit sale aux lentille', 'Petit salé aux lentilles', array['petit sale', 'saucisse aux lentille', 'saucisse lentille', 'lentille saucisse']::text[], 'dish', $r$[{"title":"Petit salé aux lentilles","intro":"Du petit salé et des saucisses mijotés avec des lentilles vertes et des carottes.","minutes":90,"calories":680,"difficulty":"Facile","imageSearch":"pork lentils stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"petit salé","plural":"petit salé","qty":800,"unit":"g","have":false},{"name":"saucisse de Morteau","plural":"saucisses de Morteau","qty":1,"unit":"","have":false},{"name":"lentille verte","plural":"lentilles vertes","qty":400,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"clou de girofle","plural":"clous de girofle","qty":2,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dessaler le petit salé 1 h dans l'eau froide, ou blanchis-le 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Mets-le dans une cocotte avec l'oignon piqué des clous, le bouquet garni, couvre d'eau et cuis 45 min.","timer":{"label":"Cuisson","min":45}},{"text":"Ajoute les lentilles, les carottes en rondelles et la saucisse piquée, et cuis 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Poivre et sers bien chaud.","timer":null}],"variant":"La classique","change":""},{"title":"Saucisses aux lentilles","intro":"Les lentilles mijotées avec des saucisses fumées.","minutes":45,"calories":620,"difficulty":"Facile","imageSearch":"sausages lentils","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"saucisse fumée","plural":"saucisses fumées","qty":4,"unit":"","have":false},{"name":"lentille verte","plural":"lentilles vertes","qty":300,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":100,"unit":"g","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":1,"unit":"","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir les lardons et l'oignon dans une cocotte.","timer":null},{"text":"Ajoute les lentilles, les carottes, le bouillon, le thym et 80 cl d'eau.","timer":null},{"text":"Ajoute les saucisses et cuis 30 min.","timer":{"label":"Cuisson","min":30}}],"kids":true,"variant":"Aux saucisses","change":"Seulement des saucisses, plus rapide."},{"title":"Lentilles mijotées végétariennes","intro":"Des lentilles fondantes aux légumes, fumées au paprika.","minutes":40,"calories":380,"difficulty":"Facile","imageSearch":"vegetarian lentil stew","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lentille verte","plural":"lentilles vertes","qty":300,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":200,"unit":"g","have":false},{"name":"paprika fumé","plural":"paprika fumé","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, le poireau et les carottes dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les lentilles, les tomates, le paprika et 80 cl d'eau.","timer":null},{"text":"Laisse mijoter