insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('buddha bowl', 'Buddha bowl', array['bowl vegetarien', 'bol complet', 'bowl']::text[], 'dish', $r$[{"title":"Buddha bowl","intro":"Un bol complet et coloré : quinoa, pois chiches rôtis, légumes, avocat et sauce au tahin.","minutes":35,"calories":560,"difficulty":"Facile","imageSearch":"buddha bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"pois chiche","plural":"pois chiches","qty":250,"unit":"g","have":false},{"name":"patate douce","plural":"patates douces","qty":1,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"chou rouge","plural":"choux rouges","qty":0.25,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"tahin","plural":"tahin","qty":3,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Mets la patate douce en cubes et les pois chiches sur une plaque avec l'huile, le paprika et le sel. Enfourne 25 min.","timer":{"label":"Four","min":25}},{"text":"Fais cuire le quinoa 12 min.","timer":{"label":"Cuisson","min":12}},{"text":"Mélange le tahin, le jus du citron et un peu d'eau pour la sauce.","timer":null},{"text":"Monte les bols avec le quinoa, les légumes râpés, l'avocat, les pois chiches et la patate douce, puis la sauce.","timer":null}],"variant":"La classique","change":""},{"title":"Buddha bowl au poulet","intro":"Un bowl complet et protéiné, au poulet.","minutes":30,"calories":580,"difficulty":"Facile","imageSearch":"chicken buddha bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"riz complet","plural":"riz complet","qty":200,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"edamame","plural":"edamame","qty":100,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":1,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":25}},{"text":"Fais griller le poulet en tranches 10 min.","timer":{"label":"Poêle","min":10}},{"text":"Fais cuire le brocoli à la vapeur 6 min.","timer":{"label":"Vapeur","min":6}},{"text":"Monte les bols et arrose de sauce soja et de sésame.","timer":null}],"variant":"Au poulet","change":"Du poulet grillé remplace les pois chiches."},{"title":"Buddha bowl au saumon","intro":"Un bowl frais au saumon, avocat et concombre.","minutes":30,"calories":600,"difficulty":"Facile","imageSearch":"salmon buddha bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"riz","plural":"riz","qty":200,"unit":"g","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":2,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"edamame","plural":"edamame","qty":100,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais cuire le saumon 8 min à la poêle et émiette-le.","timer":{"label":"Poêle","min":8}},{"text":"Coupe les légumes.","timer":null},{"text":"Monte les bols et assaisonne de sauce soja et de sésame.","timer":null}],"variant":"Au saumon","change":"Du saumon cuit remplace les pois chiches."}]$r$::jsonb, 'claude')
