insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gratin de chou fleur', 'Gratin de chou-fleur', array['chou fleur gratine', 'gratin chou fleur']::text[], 'dish', $r$[{"title":"Gratin de chou-fleur","intro":"Du chou-fleur fondant sous une béchamel gratinée à l'emmental.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"cauliflower cheese gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chou-fleur","plural":"choux-fleurs","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":30,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire le chou-fleur en bouquets 10 min dans l'eau salée.","timer":{"label":"Cuisson","min":10}},{"text":"Prépare une béchamel avec le beurre, la farine et le lait, ajoute la muscade, sel et poivre.","timer":null},{"text":"Préchauffe le four à 200 °C. Mets le chou-fleur dans un plat et nappe de béchamel.","timer":null},{"text":"Parsème d'emmental et enfourne 20 min.","timer":{"label":"Four","min":20}}],"kids":true,"variant":"La classique","change":""},{"title":"Gratin de chou-fleur et brocoli","intro":"Un gratin vert et blanc, chou-fleur et brocoli.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"cauliflower broccoli gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chou-fleur","plural":"choux-fleurs","qty":0.5,"unit":"","have":false},{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les légumes en bouquets 8 min.","timer":{"label":"Cuisson","min":8}},{"text":"Préchauffe le four à 200 °C. Bats les œufs avec la crème, sel et poivre.","timer":null},{"text":"Mets les légumes dans un plat, verse l'appareil et l'emmental.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"kids":true,"variant":"Avec brocoli","change":"Moitié chou-fleur, moitié brocoli."},{"title":"Chou-fleur rôti aux épices","intro":"Un chou-fleur doré et croquant, aux épices.","minutes":35,"calories":180,"difficulty":"Facile","imageSearch":"roasted spiced cauliflower","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chou-fleur","plural":"choux-fleurs","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"curcuma","plural":"curcuma","qty":1,"unit":"c. à c.","have":false},{"name":"yaourt grec","plural":"yaourts grecs","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 220 °C.","timer":null},{"text":"Mélange le chou-fleur en bouquets avec l'huile, les épices et le sel.","timer":null},{"text":"Enfourne 25 min, jusqu'à ce qu'il soit doré.","timer":{"label":"Four","min":25}},{"text":"Sers avec le yaourt citronné.","timer":null}],"variant":"Rôti","change":"Le chou-fleur rôtit au four avec des épices, sans béchamel."}]$r$::jsonb, 'claude')
