insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('legume roti', 'Légumes rôtis', array['legume au four', 'legume grille']::text[], 'dish', $r$[{"title":"Légumes rôtis au four","intro":"Des légumes de saison rôtis au four, dorés et caramélisés.","minutes":45,"calories":200,"difficulty":"Facile","imageSearch":"roasted vegetables tray","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":2,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":3,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"herbes de Provence","plural":"herbes de Provence","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 210 °C.","timer":null},{"text":"Coupe les légumes en morceaux de même taille.","timer":null},{"text":"Mélange-les avec l'huile, les herbes, sel et poivre sur une plaque.","timer":null},{"text":"Enfourne 35 min en remuant à mi-cuisson.","timer":{"label":"Four","min":35}}],"variant":"La classique","change":""},{"title":"Légumes sautés à la poêle","intro":"Une poêlée colorée, prête en 20 minutes.","minutes":20,"calories":160,"difficulty":"Facile","imageSearch":"sauteed vegetables","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"champignon","plural":"champignons","qty":200,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les légumes en dés.","timer":null},{"text":"Fais revenir l'oignon et le poivron dans l'huile 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute les courgettes et les champignons, et cuis 10 min à feu vif.","timer":{"label":"Poêle","min":10}},{"text":"Ajoute l'ail, sale et poivre.","timer":null}],"variant":"À la poêle","change":"Les légumes sont sautés à la poêle."},{"title":"Légumes d'hiver rôtis au miel","intro":"Des légumes racines rôtis, sucrés-salés.","minutes":50,"calories":230,"difficulty":"Facile","imageSearch":"honey roasted root vegetables","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"butternut","plural":"butternuts","qty":1,"unit":"","have":false},{"name":"panais","plural":"panais","qty":3,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":1,"unit":"","have":false},{"name":"miel","plural":"miel","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Coupe les légumes en morceaux et mélange-les avec l'huile, le miel, le thym et le sel.","timer":null},{"text":"Enfourne 40 min.","timer":{"label":"Four","min":40}}],"variant":"Légumes d'hiver","change":"Courge, panais et carottes laqués au miel."}]$r$::jsonb, 'claude')
