insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('courgette farcie', 'Courgettes farcies', array['courgette farcie au four']::text[], 'dish', $r$[{"title":"Courgettes farcies à la viande","intro":"Des courgettes garnies de viande hachée parfumée, gratinées au fromage.","minutes":50,"calories":420,"difficulty":"Facile","imageSearch":"stuffed zucchini meat","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":200,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":60,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Coupe les courgettes en deux et creuse-les.","timer":null},{"text":"Fais revenir l'oignon, l'ail, la chair des courgettes hachée et la viande 8 min, ajoute les tomates.","timer":{"label":"Poêle","min":8}},{"text":"Remplis les courgettes et parsème d'emmental.","timer":null},{"text":"Enfourne 30 min.","timer":{"label":"Four","min":30}}],"kids":true,"variant":"La classique","change":""},{"title":"Courgettes farcies au chèvre","intro":"Des courgettes fondantes au chèvre et au thym.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"zucchini stuffed goat cheese","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"chèvre frais","plural":"chèvres frais","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"chapelure","plural":"chapelure","qty":3,"unit":"c. à s.","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Coupe les courgettes en deux et creuse-les.","timer":null},{"text":"Mélange la chair hachée avec le chèvre, l'œuf, le thym, sel et poivre.","timer":null},{"text":"Remplis les courgettes, saupoudre de chapelure et arrose d'huile.","timer":null},{"text":"Enfourne 30 min.","timer":{"label":"Four","min":30}}],"variant":"Au chèvre","change":"Une farce au chèvre et aux herbes, végétarienne."},{"title":"Courgettes farcies au thon","intro":"Des courgettes farcies économiques, au thon.","minutes":45,"calories":340,"difficulty":"Facile","imageSearch":"zucchini stuffed tuna","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":50,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Coupe les courgettes en deux et creuse-les.","timer":null},{"text":"Mélange la chair hachée, le thon, les tomates et l'oignon en dés, et l'œuf.","timer":null},{"text":"Remplis les courgettes et parsème d'emmen