insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('calzone', 'Calzone', array['pizza calzone']::text[], 'dish', $r$[{"title":"Calzone","intro":"La pizza pliée en chausson, garnie de jambon, mozzarella, champignons et œuf.","minutes":100,"calories":700,"difficulty":"Moyen","imageSearch":"calzone","veg":false,"oven":true,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"farine","plural":"farines","qty":300,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":7,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"coulis de tomate","plural":"coulis de tomate","qty":15,"unit":"cl","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":2,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":3,"unit":"tranches","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Prépare la pâte à pizza et laisse-la lever 1 h.","timer":{"label":"Levée","min":60}},{"text":"Préchauffe le four à 240 °C. Partage la pâte en 2 disques.","timer":null},{"text":"Garnis une moitié de chaque disque de coulis, de jambon, de champignons et de mozzarella, et casse un œuf.","timer":null},{"text":"Replie et soude les bords.","timer":null},{"text":"Enfourne 18 min.","timer":{"label":"Four","min":18}}],"kids":true,"variant":"La classique","change":""},{"title":"Calzone végétarienne","intro":"Une calzone fondante aux épinards et à la ricotta.","minutes":100,"calories":640,"difficulty":"Moyen","imageSearch":"spinach ricotta calzone","veg":true,"oven":true,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"farine","plural":"farines","qty":300,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":7,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"épinard","plural":"épinards","qty":200,"unit":"g","have":false},{"name":"ricotta","plural":"ricotta","qty":200,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Prépare la pâte et laisse-la lever 1 h.","timer":{"label":"Levée","min":60}},{"text":"Fais tomber les épinards avec l'ail, mélange-les avec la ricotta.","timer":null},{"text":"Garnis la moitié des disques, ajoute la mozzarella et replie.","timer":null},{"text":"Enfourne 18 min à 240 °C.","timer":{"label":"Four","min":18}}],"variant":"Végétarienne","change":"Épinards, ricotta et mozzarella."},{"title":"Chaussons express à la pâte feuilletée","intro":"Des petits chaussons façon calzone, prêts en 25 minutes.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"puff pastry turnovers ham cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte feuilletée","plural":"pâtes feuilletées","qty":2,"unit":"","have":false},{"name":"coulis de tomate","plural":"coulis de tomate","qty":10,"unit":"cl","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":3,"unit":"tranches","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Découpe des disques de pâte, garnis-en la moitié de coulis, jambon et mozzarella.","timer":null},{"text":"Replie, soude les bords et dore à l'œuf battu.","timer":null},{"text":"Enfourne 18 min.","timer":{"label":"Four","min":18}}],"kids":true,"variant":"Express","change":"Avec de la pâte feuilletée toute prête."}]$r$::jsonb, 'claude')
