insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('wrap au poulet', 'Wrap au poulet', array['wrap', 'wrap poulet crudite']::text[], 'dish', $r$[{"title":"Wrap au poulet","intro":"Une galette garnie de poulet, crudités et sauce au yaourt, roulée bien serrée.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"chicken wrap","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"galette de blé","plural":"galettes de blé","qty":4,"unit":"","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"salade","plural":"salades","qty":4,"unit":"feuilles","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"yaourt grec","plural":"yaourts grecs","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le poulet en lanières et fais-le dorer avec le paprika 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Mélange le yaourt, le jus du citron et le sel.","timer":null},{"text":"Garnis les galettes de salade, tomate, carotte râpée, poulet et sauce.","timer":null},{"text":"Roule-les bien serré et coupe-les en deux.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Wrap au thon","intro":"Un wrap rapide au thon, sans cuisson.","minutes":10,"calories":420,"difficulty":"Facile","imageSearch":"tuna wrap","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"galette de blé","plural":"galettes de blé","qty":4,"unit":"","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"maïs","plural":"maïs","qty":100,"unit":"g","have":false},{"name":"salade","plural":"salades","qty":4,"unit":"feuilles","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":2,"unit":"c. à s.","have":false},{"name":"fromage blanc","plural":"fromages blanc","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Mélange le thon avec le maïs, la mayonnaise et le fromage blanc.","timer":null},{"text":"Garnis les galettes de salade, de tomate et de thon.","timer":null},{"text":"Roule-les et coupe-les en deux.","timer":null}],"variant":"Au thon","change":"Du thon et de la mayonnaise légère remplacent le poulet."},{"title":"Wrap végétarien houmous et légumes","intro":"Un wrap coloré et rassasiant, au houmous.","minutes":20,"calories":400,"difficulty":"Facile","imageSearch":"hummus veggie wrap","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"galette de blé","plural":"galettes de blé","qty":4,"unit":"","have":false},{"name":"houmous","plural":"houmous","qty":8,"unit":"c. à s.","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"pousse d'épinard","plural":"pousses d'épinard","qty":60,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":80,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais griller la courgette et le poivron en lanières dans l'huile 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Tartine les galettes de houmous.","timer":null},{"text":"Ajoute les épinards, les légumes grillés et la feta, puis roule.","timer":null}],"variant":"Végétarien","change":"Houmous et légumes grillés remplacent le poulet."}]$r$::jsonb, 'claude')
