insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('madeleine', 'Madeleines', array['madeleine maison', 'madeleine a bosse']::text[], 'dish', $r$[{"title":"Madeleines","intro":"Les petites madeleines dorées, avec leur bosse, parfumées au beurre et au citron.","minutes":80,"calories":110,"difficulty":"Facile","imageSearch":"french madeleines","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité lorraine","serves":4,"items":[{"name":"farine","plural":"farines","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":130,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":120,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fouette les œufs et le sucre jusqu'à ce que le mélange blanchisse.","timer":null},{"text":"Ajoute le zeste du citron, la farine, la levure et une pincée de sel, puis le beurre fondu.","timer":null},{"text":"Laisse reposer la pâte 1 h au frais : c'est le secret de la bosse.","timer":{"label":"Repos","min":60}},{"text":"Préchauffe le four à 220 °C. Remplis les moules beurrés aux trois quarts.","timer":null},{"text":"Enfourne 5 min, baisse à 180 °C et laisse 5 min de plus.","timer":{"label":"Four","min":10}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Madeleines au chocolat","intro":"Des madeleines au cacao, avec une coque de chocolat au fond du moule.","minutes":90,"calories":140,"difficulty":"Moyen","imageSearch":"chocolate madeleines","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":130,"unit":"g","have":false},{"name":"cacao en poudre","plural":"cacao en poudre","qty":20,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":120,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":100,"unit":"g","have":false}],"steps":[{"text":"Fouette les œufs et le sucre, puis ajoute la farine, le cacao, la levure et le beurre fondu.","timer":null},{"text":"Laisse reposer 1 h au frais.","timer":{"label":"Repos","min":60}},{"text":"Préchauffe le four à 220 °C. Remplis les moules beurrés et enfourne 5 min, puis 5 min à 180 °C.","timer":{"label":"Four","min":10}},{"text":"Fais fondre le chocolat, verses-en un peu dans chaque moule propre et repose les madeleines dessus.","timer":null},{"text":"Laisse durcir 20 min au frais avant de démouler.","timer":{"label":"Repos","min":20}}],"kids":true,"dessert":true,"variant":"Chocolat","change":"Avec du cacao dans la pâte et un fond de chocolat."},{"title":"Madeleines au miel","intro":"Des madeleines plus moelleuses, au bon goût de miel.","minutes":80,"calories":115,"difficulty":"Facile","imageSearch":"honey madeleines","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":90,"unit":"g","have":false},{"name":"miel","plural":"miels","qty":40,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":120,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Fouette les œufs et le sucre, puis ajoute le miel.","timer":null},{"text":"Ajoute la farine et la levure, puis le beurre fondu tiède.","timer":null},{"text":"Laisse reposer 1 h au frais.","timer":{"label":"Repos","min":60}},{"text":"Préchauffe le four à 220 °C, remplis les moules beurrés et enfourne 5 min, puis 5 min à 180 °C.","timer":{"label":"Four","min":10}}],"kids":true,"dessert":true,"variant":"Au miel","change":"Une partie du sucre est remplacée par du miel."}]$r$::jsonb, 'claude')
