insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('quatre quart', 'Quatre-quarts', array['quatre quart breton', 'gateau breton']::text[], 'dish', $r$[{"title":"Quatre-quarts","intro":"Le gâteau breton aux quatre ingrédients en parts égales : œufs, sucre, farine et beurre.","minutes":60,"calories":330,"difficulty":"Facile","imageSearch":"pound cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité bretonne","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":200,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":200,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C et beurre un moule à cake.","timer":null},{"text":"Fouette les œufs et le sucre jusqu'à ce qu'ils blanchissent.","timer":null},{"text":"Ajoute la farine, la levure et une pincée de sel, puis le beurre fondu.","timer":null},{"text":"Verse dans le moule et enfourne 40 min : la lame d'un couteau doit ressortir sèche.","timer":{"label":"Four","min":40}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Quatre-quarts aux pommes","intro":"Le quatre-quarts moelleux, avec des morceaux de pommes fondantes.","minutes":70,"calories":320,"difficulty":"Facile","imageSearch":"apple pound cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":150,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":150,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":150,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"pomme","plural":"pommes","qty":3,"unit":"","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Épluche les pommes et coupe-les en dés.","timer":null},{"text":"Fouette les œufs et le sucre, ajoute la farine, la levure, la cannelle, puis le beurre fondu.","timer":null},{"text":"Incorpore les pommes et verse dans un moule beurré.","timer":null},{"text":"Enfourne 45 min.","timer":{"label":"Four","min":45}}],"kids":true,"dessert":true,"variant":"Aux pommes","change":"Avec des pommes en dés dans la pâte."},{"title":"Quatre-quarts à l'orange","intro":"Un quatre-quarts tout doux, au parfum d'orange.","minutes":60,"calories":330,"difficulty":"Facile","imageSearch":"orange pound cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":200,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":180,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fouette les œufs et le sucre, ajoute le zeste et le jus de l'orange.","timer":null},{"text":"Ajoute la farine, la levure, puis le beurre fondu.","timer":null},{"text":"Verse dans un moule à cake beurré et enfourne 40 min.","timer":{"label":"Four","min":40}}],"kids":true,"dessert":true,"variant":"À l'orange","change":"Parfumé au zeste et au jus d'orange."}]$r$::jsonb, 'claude')
