insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gateau marbre', 'Gâteau marbré', array['marbre', 'cake marbre', 'marbre chocolat vanille']::text[], 'dish', $r$[{"title":"Gâteau marbré","intro":"Le cake vanille et chocolat aux jolies marbrures, comme celui du goûter.","minutes":75,"calories":340,"difficulty":"Facile","imageSearch":"marble cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beurre fondu","plural":"beurre fondu","qty":180,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":180,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"farine","plural":"farines","qty":220,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"lait","plural":"laits","qty":5,"unit":"cl","have":false},{"name":"cacao en poudre","plural":"cacao en poudre","qty":25,"unit":"g","have":false},{"name":"sucre vanillé","plural":"sucres vanillés","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C et beurre un moule à cake.","timer":null},{"text":"Fouette le beurre fondu, le sucre et le sucre vanillé, puis ajoute les œufs un à un.","timer":null},{"text":"Ajoute la farine, la levure et le lait.","timer":null},{"text":"Sépare la pâte en deux et ajoute le cacao dans une moitié.","timer":null},{"text":"Verse les pâtes en alternant dans le moule et passe une fourchette pour marbrer.","timer":null},{"text":"Enfourne 45 min.","timer":{"label":"Four","min":45}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Marbré au yaourt","intro":"Un marbré plus léger, toujours aussi moelleux.","minutes":70,"calories":260,"difficulty":"Facile","imageSearch":"marble cake slice","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"yaourt nature","plural":"yaourts nature","qty":1,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":140,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"farine","plural":"farines","qty":220,"unit":"g","have":false},{"name":"huile de tournesol","plural":"huile de tournesol","qty":5,"unit":"cl","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"cacao en poudre","plural":"cacao en poudre","qty":20,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Mélange le yaourt, le sucre et les œufs, puis la farine, la levure et l'huile.","timer":null},{"text":"Sépare la pâte en deux et ajoute le cacao dans une moitié.","timer":null},{"text":"Verse en alternant dans un moule huilé et marbre à la fourchette.","timer":null},{"text":"Enfourne 40 min.","timer":{"label":"Four","min":40}}],"kids":true,"dessert":true,"variant":"Plus léger","change":"Moins de beurre : un yaourt garde le moelleux."},{"title":"Marbré à l'orange et au cacao","intro":"Le duo chocolat orange, dans un marbré tout simple.","minutes":75,"calories":340,"difficulty":"Facile","imageSearch":"orange chocolate marble cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beurre fondu","plural":"beurre fondu","qty":180,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":180,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"farine","plural":"farines","qty":220,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"cacao en poudre","plural":"cacao en poudre","qty":25,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fouette le beurre fondu et le sucre, ajoute les œufs, puis la farine et la levure.","timer":null},{"text":"Sépare la pâte : le zeste et le jus de l'orange dans une moitié, le cacao dans l'autre.","timer":null},{"text":"Verse en alternant dans un moule beurré et marbre à la fourchette.","timer":null},{"text":"Enfourne 45 min.","timer":{"label":"Four","min":45}}],"kids":true,"dessert":true,"variant":"Orange","change":"La partie claire est parfumée à l'orange."}]$r$::jsonb, 'claude')
