insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('banana bread', 'Banana bread', array['cake a la banane', 'gateau a la banane', 'pain a la banane']::text[], 'dish', $r$[{"title":"Banana bread","intro":"Le cake américain aux bananes bien mûres, moelleux et parfumé.","minutes":70,"calories":290,"difficulty":"Facile","imageSearch":"banana bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"Recette américaine","serves":4,"items":[{"name":"banane","plural":"bananes","qty":3,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":100,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":80,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":220,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Écrase les bananes à la fourchette.","timer":null},{"text":"Mélange-les avec les œufs, le sucre et le beurre fondu.","timer":null},{"text":"Ajoute la farine, la levure et la cannelle sans trop mélanger.","timer":null},{"text":"Verse dans un moule à cake beurré et enfourne 50 min.","timer":{"label":"Four","min":50}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Banana bread aux pépites de chocolat","intro":"Le banana bread gourmand, plein de pépites fondantes.","minutes":70,"calories":340,"difficulty":"Facile","imageSearch":"chocolate chip banana bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"banane","plural":"bananes","qty":3,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":90,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":80,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":220,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"pépites de chocolat","plural":"pépites de chocolat","qty":100,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Écrase les bananes et mélange-les avec les œufs, le sucre et le beurre fondu.","timer":null},{"text":"Ajoute la farine et la levure, puis les pépites de chocolat.","timer":null},{"text":"Verse dans un moule à cake et enfourne 50 min.","timer":{"label":"Four","min":50}}],"kids":true,"dessert":true,"variant":"Chocolat","change":"Avec des pépites de chocolat."},{"title":"Banana bread sans sucre ajouté","intro":"Un cake doux et léger, sucré seulement par les fruits.","minutes":70,"calories":210,"difficulty":"Facile","imageSearch":"healthy banana bread oats","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"banane","plural":"bananes","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"huile de coco","plural":"huile de coco","qty":4,"unit":"c. à s.","have":false},{"name":"farine complète","plural":"farine complète","qty":150,"unit":"g","have":false},{"name":"flocons d'avoine","plural":"flocons d'avoine","qty":60,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Écrase les bananes et mélange-les avec les œufs et l'huile fondue.","timer":null},{"text":"Ajoute la farine, les flocons, la levure et la cannelle.","timer":null},{"text":"Verse dans un moule à cake et enfourne 45 min.","timer":{"label":"Four","min":45}}],"kids":true,"dessert":true,"variant":"Sans sucre ajouté","change":"Les bananes très mûres su