insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('cheesecake', 'Cheesecake', array['cheese cake', 'cheesecake new york', 'cheesecake maison']::text[], 'dish', $r$[{"title":"Cheesecake new-yorkais","intro":"Le cheesecake crémeux sur sa base de biscuits, cuit doucement au four.","minutes":90,"calories":480,"difficulty":"Moyen","imageSearch":"new york cheesecake","veg":true,"oven":true,"cold":false,"missing":"","origin":"Recette new-yorkaise","serves":4,"items":[{"name":"biscuits secs","plural":"biscuits secs","qty":200,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":80,"unit":"g","have":false},{"name":"fromage frais type Philadelphia","plural":"fromage frais type Philadelphia","qty":600,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C. Écrase les biscuits et mélange-les au beurre fondu.","timer":null},{"text":"Tasse ce mélange au fond d'un moule à charnière.","timer":null},{"text":"Fouette le fromage frais, le sucre, la crème, le zeste du citron, puis les œufs un à un.","timer":null},{"text":"Verse sur la base et enfourne 1 h.","timer":{"label":"Four","min":60}},{"text":"Laisse refroidir dans le four entrouvert, puis au moins 4 h au frais.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Cheesecake sans cuisson","intro":"Un cheesecake frais et léger, qui se prépare la veille.","minutes":30,"calories":420,"difficulty":"Facile","imageSearch":"no bake cheesecake","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"biscuits secs","plural":"biscuits secs","qty":200,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":80,"unit":"g","have":false},{"name":"fromage frais type Philadelphia","plural":"fromage frais type Philadelphia","qty":400,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":25,"unit":"cl","have":false},{"name":"sucre glace","plural":"sucre glace","qty":80,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false}],"steps":[{"text":"Écrase les biscuits, mélange-les au beurre fondu et tasse au fond d'un moule à charnière.","timer":null},{"text":"Fouette la crème bien froide en chantilly.","timer":null},{"text":"Mélange le fromage frais, le sucre glace et le jus du citron, puis incorpore la chantilly.","timer":null},{"text":"Étale sur la base et laisse prendre au moins 6 h au frais.","timer":null}],"dessert":true,"variant":"Sans four","change":"Pris au frais, sans passer par le four."},{"title":"Cheesecake aux fruits rouges","intro":"Le cheesecake crémeux, nappé d'un coulis de fruits rouges.","minutes":100,"calories":500,"difficulty":"Moyen","imageSearch":"berry cheesecake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"biscuits secs","plural":"biscuits secs","qty":200,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":80,"unit":"g","have":false},{"name":"fromage frais type Philadelphia","plural":"fromage frais type Philadelphia","qty":600,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":180,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"fruits rouges surgelés","plural":"fruits rouges surgelés","qty":300,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C. Tasse les biscuits écrasés et le beurre au fond d'un moule.","timer":null},{"text":"Fouette le fromage frais, 150 g de sucre, la crème, puis les œufs.","timer":null},{"text":"Verse sur la base et enfourne 1 h. Laisse refroidir puis 4 h au frais.","timer":{"label":"Four","min":60}},{"text":"Fais cuire les fruits rouges 10 min avec le reste du sucre, puis laisse refroidir.","timer":{"label":"Cuisson","min":10}},{"text":"Nappe le cheesecake du coulis au moment de servir.","timer":null}],"dessert":true,"variant":"Fruits rouges","change":"Avec un coulis de fruits rouges sur le dessus."}]$r$::jsonb, 'claude')
