insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('carrot cake', 'Carrot cake', array['gateau aux carotte', 'gateau a la carotte', 'cake aux carotte']::text[], 'dish', $r$[{"title":"Carrot cake","intro":"Le gâteau moelleux aux carottes et aux épices, avec son glaçage au fromage frais.","minutes":80,"calories":450,"difficulty":"Moyen","imageSearch":"carrot cake frosting","veg":true,"oven":true,"cold":false,"missing":"","origin":"Recette anglo-saxonne","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":150,"unit":"g","have":false},{"name":"huile de tournesol","plural":"huile de tournesol","qty":15,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"cannelle","plural":"cannelle","qty":2,"unit":"c. à c.","have":false},{"name":"fromage frais type Philadelphia","plural":"fromage frais type Philadelphia","qty":200,"unit":"g","have":false},{"name":"sucre glace","plural":"sucre glace","qty":60,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Râpe finement les carottes.","timer":null},{"text":"Fouette les œufs, le sucre roux et l'huile.","timer":null},{"text":"Ajoute la farine, la levure et la cannelle, puis les carottes.","timer":null},{"text":"Verse dans un moule beurré et enfourne 45 min. Laisse refroidir.","timer":{"label":"Four","min":45}},{"text":"Fouette le fromage frais et le sucre glace, et étale ce glaçage sur le gâteau.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Carrot cake aux noix","intro":"Le carrot cake encore plus gourmand, avec des noix croquantes.","minutes":80,"calories":500,"difficulty":"Moyen","imageSearch":"walnut carrot cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":150,"unit":"g","have":false},{"name":"huile de tournesol","plural":"huile de tournesol","qty":15,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"cannelle","plural":"cannelle","qty":2,"unit":"c. à c.","have":false},{"name":"cerneaux de noix","plural":"cerneaux de noix","qty":80,"unit":"g","have":false},{"name":"fromage frais type Philadelphia","plural":"fromage frais type Philadelphia","qty":200,"unit":"g","have":false},{"name":"sucre glace","plural":"sucre glace","qty":60,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Râpe les carottes et concasse les noix.","timer":null},{"text":"Fouette les œufs, le sucre et l'huile, puis ajoute la farine, la levure et la cannelle.","timer":null},{"text":"Ajoute les carottes et les deux tiers des noix.","timer":null},{"text":"Verse dans un moule et enfourne 45 min. Laisse refroidir.","timer":{"label":"Four","min":45}},{"text":"Couvre du glaçage fromage frais et sucre glace, puis du reste des noix.","timer":null}],"dessert":true,"variant":"Aux noix","change":"Avec des noix concassées dans la pâte et sur le glaçage."},{"title":"Carrot cake léger","intro":"Un carrot cake moelleux pour le goûter de tous les jours.","minutes":65,"calories":280,"difficulty":"Facile","imageSearch":"healthy carrot cake loaf","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":90,"unit":"g","have":false},{"name":"huile de tournesol","plural":"huile de tournesol","qty":8,"unit":"cl","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":1,"unit":"","have":false},{"name":"farine","plural":"farines","qty":220,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"cannelle","plural":"cannelle","qty":2,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Râpe les carottes.","timer":null},{"text":"Fouette les œufs, le sucre, l'huile et le yaourt.","timer":null},{"text":"Ajoute la farine, la levure et la cannelle, puis les carottes.","timer":null},{"text":"Verse dans un moule à cake et enfourne 45 min.","timer":{"label":"Four","min":45}}],"kids":true,"dessert":true,"variant":"Plus léger","change":"Sans glaçage, avec moins de sucre et d'huile."}]$r$::jsonb, 'claude')
