insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('financier', 'Financiers', array['financier aux amande']::text[], 'dish', $r$[{"title":"Financiers aux amandes","intro":"Les petits gâteaux aux amandes et au beurre noisette, croustillants dehors et fondants dedans.","minutes":40,"calories":130,"difficulty":"Facile","imageSearch":"almond financiers","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poudre d'amande","plural":"poudre d'amande","qty":100,"unit":"g","have":false},{"name":"sucre glace","plural":"sucre glace","qty":150,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":50,"unit":"g","have":false},{"name":"blanc d'œuf","plural":"blancs d'œufs","qty":4,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":120,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Fais chauffer le beurre jusqu'à ce qu'il soit doré et sente la noisette.","timer":{"label":"Cuisson","min":5}},{"text":"Mélange la poudre d'amande, le sucre glace et la farine, puis les blancs non battus.","timer":null},{"text":"Ajoute le beurre noisette tiède et remplis des moules beurrés.","timer":null},{"text":"Enfourne 12 min.","timer":{"label":"Four","min":12}}],"dessert":true,"variant":"La classique","change":""},{"title":"Financiers aux framboises","intro":"Les financiers aux amandes, avec une framboise acidulée.","minutes":40,"calories":135,"difficulty":"Facile","imageSearch":"raspberry financiers","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poudre d'amande","plural":"poudre d'amande","qty":100,"unit":"g","have":false},{"name":"sucre glace","plural":"sucre glace","qty":150,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":50,"unit":"g","have":false},{"name":"blanc d'œuf","plural":"blancs d'œufs","qty":4,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":120,"unit":"g","have":false},{"name":"framboise","plural":"framboises","qty":125,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C et fais dorer le beurre.","timer":{"label":"Cuisson","min":5}},{"text":"Mélange la poudre d'amande, le sucre glace, la farine et les blancs.","timer":null},{"text":"Ajoute le beurre noisette et remplis les moules.","timer":null},{"text":"Enfonce une ou deux framboises dans chaque financier.","timer":null},{"text":"Enfourne 14 min.","timer":{"label":"Four","min":14}}],"dessert":true,"variant":"Framboises","change":"Avec une framboise au cœur de chaque financier."},{"title":"Financiers au chocolat","intro":"Des financiers chocolatés, pour finir les blancs d'œufs.","minutes":40,"calories":150,"difficulty":"Facile","imageSearch":"chocolate financiers","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poudre d'amande","plural":"poudre d'amande","qty":80,"unit":"g","have":false},{"name":"sucre glace","plural":"sucre glace","qty":150,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"cacao en poudre","plural":"cacao en poudre","qty":20,"unit":"g","have":false},{"name":"blanc d'œuf","plural":"blancs d'œufs","qty":4,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":120,"unit":"g","have":false},{"name":"pépites de chocolat","plural":"pépites de chocolat","qty":50,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C et fais dorer le beurre.","timer":{"label":"Cuisson","min":5}},{"text":"Mélange la poudre d'amande, le sucre glace, la farine, le cacao et les blancs.","timer":null},{"text":"Ajoute le beurre noisette, puis les pépites.","timer":null},{"text":"Remplis des moules beurrés et enfourne 12 min.","timer":{"label":"Four","min":12}}],"dessert":true,"variant":"Chocolat","change":"Avec du cacao dans la pâte et des pépites."}]$r$::jsonb, 'claude')
