insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('sable', 'Sablés', array['biscuit sable', 'petit sable', 'sable maison']::text[], 'dish', $r$[{"title":"Sablés au beurre","intro":"Les petits biscuits sablés pur beurre, à découper à l'emporte-pièce.","minutes":50,"calories":90,"difficulty":"Facile","imageSearch":"butter shortbread cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":125,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"sucre vanillé","plural":"sucres vanillés","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Mélange le beurre mou, le sucre, le sucre vanillé et une pincée de sel.","timer":null},{"text":"Ajoute l'œuf, puis la farine, et forme une boule sans trop travailler.","timer":null},{"text":"Laisse reposer 30 min au frais.","timer":{"label":"Repos","min":30}},{"text":"Préchauffe le four à 180 °C. Étale la pâte et découpe les sablés.","timer":null},{"text":"Enfourne 10 min : ils doivent rester clairs.","timer":{"label":"Four","min":10}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Sablés au citron","intro":"Des sablés frais et parfumés au citron.","minutes":50,"calories":90,"difficulty":"Facile","imageSearch":"lemon shortbread cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":125,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false}],"steps":[{"text":"Mélange le beurre mou, le sucre et le zeste du citron.","timer":null},{"text":"Ajoute l'œuf, puis la farine, et forme une boule.","timer":null},{"text":"Laisse reposer 30 min au frais.","timer":{"label":"Repos","min":30}},{"text":"Préchauffe le four à 180 °C, étale la pâte et découpe les sablés.","timer":null},{"text":"Enfourne 10 min.","timer":{"label":"Four","min":10}}],"kids":true,"dessert":true,"variant":"Citron","change":"Avec le zeste d'un citron dans la pâte."},{"title":"Sablés au chocolat","intro":"Des sablés cacao avec des pépites, pour les gourmands.","minutes":50,"calories":105,"difficulty":"Facile","imageSearch":"chocolate shortbread cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":220,"unit":"g","have":false},{"name":"cacao en poudre","plural":"cacao en poudre","qty":30,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":125,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"pépites de chocolat","plural":"pépites de chocolat","qty":60,"unit":"g","have":false}],"steps":[{"text":"Mélange le beurre mou et le sucre, puis l'œuf.","timer":null},{"text":"Ajoute la farine, le cacao et les pépites, et forme une boule.","timer":null},{"text":"Laisse reposer 30 min au frais.","timer":{"label":"Repos","min":30}},{"text":"Préchauffe le four à 180 °C, étale et découpe les sablés.","timer":null},{"text":"Enfourne 10 min.","timer":{"label":"Four","min":10}}],"kids":true,"dessert":true,"variant":"Chocolat","change":"Avec du cacao et des pépites de chocolat."}]$r$::jsonb, 'claude')
