insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('brioche', 'Brioche', array['brioche maison', 'brioche moelleuse']::text[], 'dish', $r$[{"title":"Brioche maison","intro":"Une brioche moelleuse et filante, pour le petit-déjeuner du week-end.","minutes":180,"calories":320,"difficulty":"Moyen","imageSearch":"homemade brioche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":500,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":10,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":150,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Délaye la levure dans le lait tiède.","timer":null},{"text":"Mélange la farine, le sucre, 1 c. à c. de sel, 3 œufs et le lait, puis pétris 10 min.","timer":{"label":"Pétrissage","min":10}},{"text":"Ajoute le beurre mou en morceaux et pétris encore jusqu'à ce que la pâte soit lisse.","timer":null},{"text":"Laisse lever 1 h 30 sous un torchon.","timer":{"label":"Levée","min":90}},{"text":"Façonne 6 boules dans un moule à cake et laisse lever encore 45 min.","timer":{"label":"Levée","min":45}},{"text":"Préchauffe le four à 180 °C, dore au dernier œuf battu et enfourne 30 min.","timer":{"label":"Four","min":30}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Brioche aux pépites de chocolat","intro":"La brioche moelleuse des goûters, pleine de pépites.","minutes":180,"calories":360,"difficulty":"Moyen","imageSearch":"chocolate chip brioche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":500,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":10,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":150,"unit":"g","have":false},{"name":"pépites de chocolat","plural":"pépites de chocolat","qty":120,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Délaye la levure dans le lait tiède, puis pétris avec la farine, le sucre, le sel et 3 œufs.","timer":{"label":"Pétrissage","min":10}},{"text":"Ajoute le beurre mou, puis les pépites, en pétrissant.","timer":null},{"text":"Laisse lever 1 h 30.","timer":{"label":"Levée","min":90}},{"text":"Façonne dans un moule à cake et laisse lever 45 min.","timer":{"label":"Levée","min":45}},{"text":"Dore au dernier œuf et enfourne 30 min à 180 °C.","timer":{"label":"Four","min":30}}],"kids":true,"dessert":true,"variant":"Chocolat","change":"Avec des pépites de chocolat dans la pâte."},{"title":"Brioche tressée","intro":"Une belle brioche tressée, à poser au milieu de la table.","minutes":180,"calories":330,"difficulty":"Difficile","imageSearch":"braided brioche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":500,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":10,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":150,"unit":"g","have":false},{"name":"sucre perlé","plural":"sucre perlé","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Délaye la levure dans le lait tiède, puis pétris avec la farine, le sucre, le sel et 3 œufs.","timer":{"label":"Pétrissage","min":10}},{"text":"Ajoute le beurre mou et pétris jusqu'à ce que la pâte soit lisse.","timer":null},{"text":"Laisse lever 1 h 30.","timer":{"label":"Levée","min":90}},{"text":"Partage la pâte en 3 boudins et tresse-les sur une plaque. Laisse lever 45 min.","timer":{"label":"Levée","min":45}},{"text":"Dore à l'œuf battu, parsème de sucre perlé et enfourne 25 min à 180 °C.","timer":{"label":"Four","min":25}}],"kids":true,"dessert":true,"variant":"Tressée","change":"Façonnée en tresse et parsemée de sucre perlé."}]$r$::jsonb, 'claude')
