insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('beignet', 'Beignets', array['beignet au sucre', 'beignet maison']::text[], 'dish', $r$[{"title":"Beignets au sucre","intro":"Des beignets moelleux, dorés à la friture et roulés dans le sucre.","minutes":150,"calories":280,"difficulty":"Moyen","imageSearch":"sugar donuts","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":400,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":10,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":50,"unit":"g","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Délaye la levure dans le lait tiède.","timer":null},{"text":"Mélange la farine, 50 g de sucre, une pincée de sel, les œufs, le lait et le beurre fondu, et pétris 5 min.","timer":null},{"text":"Laisse lever 1 h 30.","timer":{"label":"Levée","min":90}},{"text":"Étale la pâte sur 1 cm, découpe des ronds et laisse lever 30 min.","timer":{"label":"Levée","min":30}},{"text":"Fais frire les beignets 2 min de chaque côté dans l'huile chaude.","timer":{"label":"Friture","min":4}},{"text":"Égoutte-les et roule-les dans le reste du sucre.","timer":null}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Beignets aux pommes","intro":"Les beignets de pommes de carnaval, croustillants et fondants.","minutes":40,"calories":250,"difficulty":"Facile","imageSearch":"apple fritters","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme","plural":"pommes","qty":4,"unit":"","have":false},{"name":"farine","plural":"farines","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":30,"unit":"g","have":false},{"name":"sucre glace","plural":"sucre glace","qty":2,"unit":"c. à s.","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Mélange la farine, le sucre, les œufs et le lait pour une pâte lisse.","timer":null},{"text":"Épluche les pommes, retire le cœur et coupe-les en rondelles.","timer":null},{"text":"Trempe les rondelles dans la pâte.","timer":null},{"text":"Fais-les frire 2 min de chaque côté dans l'huile chaude.","timer":{"label":"Friture","min":4}},{"text":"Égoutte et saupoudre de sucre glace.","timer":null}],"kids":true,"dessert":true,"variant":"Aux pommes","change":"Des rondelles de pommes enrobées de pâte à beignets."},{"title":"Beignets à la banane","intro":"Des beignets de banane dorés, comme aux Antilles.","minutes":30,"calories":240,"difficulty":"Facile","imageSearch":"banana fritters","veg":true,"oven":false,"cold":false,"missing":"","origin":"Inspiration antillaise","serves":4,"items":[{"name":"banane","plural":"bananes","qty":4,"unit":"","have":false},{"name":"farine","plural":"farines","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":30,"unit":"g","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Écrase 2 bananes et mélange-les avec la farine, le sucre, la cannelle, l'œuf et le lait.","timer":null},{"text":"Coupe les autres bananes en rondelles et ajoute-les à la pâte.","timer":null},{"text":"Fais frire des cuillerées de pâte 2 min de chaque côté.","timer":{"label":"Friture","min":4}},{"text":"Égoutte sur du papier absorbant et sers tiède.","timer":null}],"kids":true,"dessert":true,"variant":"Banane","change":"Des morceaux de banane dans une pâte légère."}]$r$::jsonb, 'claude')
