insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('panna cotta', 'Panna cotta', array['pannacotta', 'panna cotta couli']::text[], 'dish', $r$[{"title":"Panna cotta au coulis de fruits rouges","intro":"La crème italienne tremblotante, à la vanille, avec un coulis de fruits rouges.","minutes":20,"calories":330,"difficulty":"Facile","imageSearch":"panna cotta berry coulis","veg":true,"oven":false,"cold":true,"missing":"","origin":"Dessert italien","serves":4,"items":[{"name":"crème liquide entière","plural":"crème liquide entière","qty":50,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"gélatine","plural":"feuilles de gélatine","qty":3,"unit":"feuilles","have":false},{"name":"gousse de vanille","plural":"gousses de vanille","qty":1,"unit":"","have":false},{"name":"fruits rouges surgelés","plural":"fruits rouges surgelés","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais ramollir la gélatine dans de l'eau froide.","timer":null},{"text":"Chauffe la crème avec 60 g de sucre et la vanille fendue, sans faire bouillir.","timer":{"label":"Cuisson","min":5}},{"text":"Hors du feu, ajoute la gélatine essorée et mélange.","timer":null},{"text":"Verse dans des verrines et laisse prendre 4 h au frais.","timer":null},{"text":"Mixe les fruits rouges avec le reste du sucre et nappe au moment de servir.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Panna cotta à la mangue","intro":"Une panna cotta toute douce, sous un coulis de mangue exotique.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"mango panna cotta","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"crème liquide entière","plural":"crème liquide entière","qty":50,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"gélatine","plural":"feuilles de gélatine","qty":3,"unit":"feuilles","have":f