insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('ile flottante', 'Île flottante', array['oeuf a la neige']::text[], 'dish', $r$[{"title":"Île flottante","intro":"Des blancs en neige pochés sur une crème anglaise, avec un filet de caramel.","minutes":45,"calories":300,"difficulty":"Moyen","imageSearch":"floating island dessert","veg":true,"oven":false,"cold":true,"missing":"","origin":"Dessert français","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":6,"unit":"","have":false},{"name":"lait","plural":"laits","qty":75,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":180,"unit":"g","have":false},{"name":"gousse de vanille","plural":"gousses de vanille","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Chauffe le lait avec la vanille fendue. Fouette les jaunes avec 80 g de sucre.","timer":null},{"text":"Verse le lait chaud sur les jaunes, puis fais épaissir à feu doux sans bouillir, en remuant : c'est prêt quand la crème nappe la cuillère.","timer":{"label":"Cuisson","min":10}},{"text":"Monte les blancs en neige avec une pincée de sel et 40 g de sucre.","timer":null},{"text":"Poche des boules de blancs 1 min de chaque côté dans de l'eau frémissante.","timer":{"label":"Cuisson","min":2}},{"text":"Fais un caramel avec le reste du sucre et 2 c. à s. d'eau.","timer":null},{"text":"Pose les blancs sur la crème froide et arrose de caramel.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Îles flottantes au micro-ondes","intro":"La version rapide, avec une crème anglaise du commerce.","minutes":15,"calories":250,"difficulty":"Facile","imageSearch":"floating island bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"blanc d'œuf","plural":"blancs d'œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"crème anglaise","plural":"crème anglaise","qty":50,"unit":"cl","have":false},{"name":"caramel liquide","plural":"caramel liquide","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Monte les blancs en neige ferme en ajoutant le sucre à la fin.","timer":null},{"text":"Forme 4 tas de blancs dans des tasses légèrement huilées.","timer":null},{"text":"Fais-les cuire 30 secondes au micro-ondes.","timer":null},{"text":"Démoule sur la crème anglaise et arrose de caramel.","timer":null}],"kids":true,"dessert":true,"variant":"Express","change":"Les blancs cuisent au micro-ondes, en quelques secondes."},{"title":"Île flottante aux pralines roses","intro":"L'île flottante lyonnaise, croquante et rose.","minutes":45,"calories":330,"difficulty":"Moyen","imageSearch":"floating island pink pralines","veg":true,"oven":false,"cold":true,"missing":"","origin":"Inspiration lyonnaise","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":6,"unit":"","have":false},{"name":"lait","plural":"laits","qty":75,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":130,"unit":"g","have":false},{"name":"gousse de vanille","plural":"gousses de vanille","qty":1,"unit":"","have":false},{"name":"pralines roses","plural":"pralines roses","qty":60,"unit":"g","have":false}],"steps":[{"text":"Prépare la crème anglaise : lait chaud vanillé versé sur les jaunes fouettés avec 80 g de sucre, puis épaissie à feu doux.","timer":{"label":"Cuisson","min":10}},{"text":"Laisse refroidir au frais.","timer":null},{"text":"Monte les blancs en neige avec le reste du sucre.","timer":null},{"text":"Poche les blancs 1 min de chaque côté dans de l'eau frémissante.","timer":{"label":"Cuisson","min":2}},{"text":"Pose-les sur la crème et parsème de pralines concassées.","timer":null}],"dessert":true,"variant":"Pralines roses","change":"Parsemée de pralines roses concassées."}]$r$::jsonb, 'claude')
