insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('compote de pomme', 'Compote de pommes', array['compote', 'compote maison', 'compote pomme']::text[], 'dish', $r$[{"title":"Compote de pommes","intro":"La compote maison toute simple, avec juste des pommes et un peu de cannelle.","minutes":30,"calories":120,"difficulty":"Facile","imageSearch":"applesauce bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pomme","plural":"pommes","qty":8,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":2,"unit":"c. à s.","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Épluche les pommes, retire le cœur et coupe-les en morceaux.","timer":null},{"text":"Mets-les dans une casserole avec 10 cl d'eau, le sucre et la cannelle.","timer":null},{"text":"Fais cuire 20 min à couvert en remuant de temps en temps.","timer":{"label":"Cuisson","min":20}},{"text":"Écrase à la fourchette ou mixe, selon la texture que tu aimes.","timer":null}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Compote pommes-poires","intro":"Une compote douce, sucrée seulement par les fruits.","minutes":30,"calories":100,"difficulty":"Facile","imageSearch":"apple pear compote","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pomme","plural":"pommes","qty":4,"unit":"","have":false},{"name":"poire","plural":"poires","qty":4,"unit":"","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Épluche les fruits, retire le cœur et coupe-les en morceaux.","timer":null},{"text":"Mets-les dans une casserole avec 5 cl d'eau et la cannelle.","timer":null},{"text":"Fais cuire 20 min à couvert.","timer":{"label":"Cuisson","min":20}},{"text":"Écrase ou mixe, puis laisse refroidir.","timer":null}],"kids":true,"dessert":true,"variant":"Pommes et poires","change":"Moitié pommes, moitié poires, sans sucre ajouté."},{"title":"Compote pommes-fraises","intro":"Une compote rose et fruitée qui plaît aux enfants.","minutes":30,"calories":110,"difficulty":"Facile","imageSearch":"apple strawberry compote","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pomme","plural":"pommes","qty":6,"unit":"","have":false},{"name":"fraise","plural":"fraises","qty":250,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Épluche les pommes et coupe-les en morceaux.","timer":null},{"text":"Fais-les cuire 15 min à couvert avec 5 cl d'eau et le sucre.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute les fraises équeutées et laisse cuire 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Mixe et laisse refroidir.","timer":null}],"kids":true,"dessert":true,"variant":"Pommes et fraises","change":"Avec des fraises ajoutées en fin de cuisson."}]$r$::jsonb, 'claude')
