insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('creme caramel', 'Crème caramel', array['creme renversee', 'creme caramel maison', 'flan caramel']::text[], 'dish', $r$[{"title":"Crème caramel","intro":"La crème renversée vanillée, nappée de son caramel blond.","minutes":70,"calories":250,"difficulty":"Moyen","imageSearch":"creme caramel","veg":true,"oven":true,"cold":false,"missing":"","origin":"Dessert français","serves":4,"items":[{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":180,"unit":"g","have":false},{"name":"gousse de vanille","plural":"gousses de vanille","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C.","timer":null},{"text":"Fais un caramel avec 100 g de sucre et 3 c. à s. d'eau, et verse-le au fond des ramequins.","timer":null},{"text":"Chauffe le lait avec la vanille fendue.","timer":null},{"text":"Fouette les œufs et le reste du sucre, puis verse le lait chaud dessus.","timer":null},{"text":"Remplis les ramequins et enfourne 40 min au bain-marie.","timer":{"label":"Four","min":40}},{"text":"Laisse refroidir puis 2 h au frais avant de démouler.","timer":null}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Crème caramel au lait de coco","intro":"Une crème renversée au parfum des îles.","minutes":70,"calories":280,"difficulty":"Moyen","imageSearch":"coconut flan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":170,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C et fais un caramel avec 100 g de sucre et un peu d'eau.","timer":null},{"text":"Verse-le au fond des ramequins.","timer":null},{"text":"Fouette les œufs avec le reste du sucre, puis le lait de coco et le lait.","timer":null},{"text":"Remplis les ramequins et enfourne 40 min au bain-marie.","timer":{"label":"Four","min":40}},{"text":"Laisse 2 h au frais avant de démouler.","timer":null}],"kids":true,"dessert":true,"variant":"Coco","change":"Le lait de coco remplace une partie du lait."},{"title":"Crème caramel à la cocotte-minute","intro":"La crème caramel sans allumer le four.","minutes":40,"calories":250,"difficulty":"Moyen","imageSearch":"creme caramel ramekin","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":180,"unit":"g","have":false},{"name":"sucre vanillé","plural":"sucres vanillés","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais un caramel avec 100 g de sucre et un peu d'eau, et verse-le dans des ramequins.","timer":null},{"text":"Fouette les œufs, le reste du sucre et le sucre vanillé, puis ajoute le lait chaud.","timer":null},{"text":"Remplis les ramequins et couvre-les de papier aluminium.","timer":null},{"text":"Pose-les dans la cocotte avec 2 cm d'eau et compte 6 min après le sifflement.","timer":{"label":"Cuisson","min":6}},{"text":"Laisse refroidir puis 2 h au frais.","timer":null}],"kids":true,"dessert":true,"variant":"Sans four","change":"Cuite à la vapeur dans une cocotte-minute."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poire belle helene', 'Poires belle-Hélène', array['poire au chocolat', 'poire pochee']::text[], 'dish', $r$[{"title":"Poires belle-Hélène","intro":"Des poires pochées au sirop vanillé, nappées de chocolat chaud.","minutes":40,"calories":330,"difficulty":"Facile","imageSearch":"poire belle helene","veg":true,"oven":false,"cold":true,"missing":"","origin":"Dessert français","serves":4,"items":[{"name":"poire","plural":"poires","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":150,"unit":"g","have":false},{"name":"gousse de vanille","plural":"gousses de vanille","qty":1,"unit":"","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":150,"unit":"g","have":false},{"name":"crème liquide","plural":"crème liquide","qty":15,"unit":"cl","have":false},{"name":"glace vanille","plural":"glace vanille","qty":50,"unit":"cl","have":false}],"steps":[{"text":"Porte à ébullition 1 litre d'eau avec le sucre et la vanille fendue.","timer":null},{"text":"Épluche les poires en gardant la queue et poche-les 20 min dans le sirop.","timer":{"label":"Cuisson","min":20}},{"text":"Laisse-les refroidir dans le sirop.","timer":null},{"text":"Fais fondre le chocolat dans la crème chaude.","timer":null},{"text":"Sers chaque poire avec une boule de glace et la sauce chocolat.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Poires pochées au vin rouge","intro":"Des poires rouges et parfumées, pour un dessert d'hiver.","minutes":50,"calories":250,"difficulty":"Facile","imageSearch":"poached pears red wine","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"poire","plural":"poires","qty":4,"unit":"","have":false},{"name":"vin rouge","plural":"vin rouge","qty":75,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"bâton de cannelle","plural":"bâtons de cannelle","qty":1,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false}],"steps":[{"text":"Porte à ébullition le vin avec le sucre, la cannelle et le zeste de l'orange.","timer":null},{"text":"Épluche les poires en gardant la queue.","timer":null},{"text":"Poche-les 30 min dans le vin frémissant en les retournant.","timer":{"label":"Cuisson","min":30}},{"text":"Retire les poires et fais réduire le vin en sirop.","timer":{"label":"Cuisson","min":10}},{"text":"Sers tiède ou froid, nappé de sirop.","timer":null}],"dessert":true,"variant":"Au vin","change":"Pochées dans un vin rouge aux épices."},{"title":"Poires rôties au miel","intro":"Des poires fondantes et caramélisées au miel.","minutes":35,"calories":180,"difficulty":"Facile","imageSearch":"roasted pears honey","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poire","plural":"poires","qty":4,"unit":"","have":false},{"name":"miel","plural":"miels","qty":3,"unit":"c. à s.","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Coupe les poires en deux et retire le cœur.","timer":null},{"text":"Pose-les dans un plat, arrose de miel, parsème de beurre et de cannelle.","timer":null},{"text":"Enfourne 25 min en arrosant à mi-cuisson.","timer":{"label":"Four","min":25}}],"kids":true,"dessert":true,"variant":"Rôties","change":"Rôties au four avec du miel, sans sirop."}]$r$::jsonb, 'claude')
