insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('charlotte aux fraise', 'Charlotte aux fraises', array['charlotte', 'charlotte fraise']::text[], 'dish', $r$[{"title":"Charlotte aux fraises","intro":"Des biscuits à la cuillère autour d'une mousse légère aux fraises.","minutes":40,"calories":350,"difficulty":"Moyen","imageSearch":"strawberry charlotte","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"biscuits à la cuillère","plural":"biscuits à la cuillère","qty":24,"unit":"","have":false},{"name":"fraise","plural":"fraises","qty":500,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":30,"unit":"cl","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":250,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"gélatine","plural":"feuilles de gélatine","qty":4,"unit":"feuilles","have":false}],"steps":[{"text":"Fais ramollir la gélatine dans l'eau froide. Mixe la moitié des fraises avec le sucre.","timer":null},{"text":"Chauffe un peu de ce coulis et fais-y fondre la gélatine, puis mélange au reste.","timer":null},{"text":"Fouette la crème en chantilly et mélange-la au fromage blanc et au coulis.","timer":null},{"text":"Trempe rapidement les biscuits dans de l'eau sucrée et tapisse un moule.","timer":null},{"text":"Alterne mousse et fraises coupées, puis couvre de biscuits.","timer":null},{"text":"Laisse prendre 6 h au frais avant de démouler.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Charlotte aux framboises","intro":"La charlotte acidulée aux framboises.","minutes":40,"calories":350,"difficulty":"Moyen","imageSearch":"raspberry charlotte","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"biscuits à la cuillère","plural":"biscuits à la cuillère","qty":24,"unit":"","have":false},{"name":"framboise","plural":"framboises","qty":400,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":30,"unit":"cl","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":250,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"gélatine","plural":"feuilles de gélatine","qty":4,"unit":"feuilles","have":false}],"steps":[{"text":"Fais ramollir la gélatine. Mixe la moitié des framboises avec le sucre et fais fondre la gélatine dans un peu de coulis chaud.","timer":null},{"text":"Fouette la crème en chantilly et mélange-la au fromage blanc et au coulis.","timer":null},{"text":"Tapisse un moule de biscuits trempés dans de l'eau sucrée.","timer":null},{"text":"Alterne mousse et framboises entières, puis couvre de biscuits.","timer":null},{"text":"Laisse prendre 6 h au frais.","timer":null}],"dessert":true,"variant":"Framboises","change":"Avec des framboises à la place des fraises."},{"title":"Charlotte au chocolat","intro":"La charlotte des gourmands, garnie de mousse au chocolat.","minutes":40,"calories":420,"difficulty":"Moyen","imageSearch":"chocolate charlotte","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"biscuits à la cuillère","plural":"biscuits à la cuillère","qty":24,"unit":"","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":5,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Fais fondre le chocolat et laisse tiédir, puis ajoute les jaunes d'œufs.","timer":null},{"text":"Monte les blancs en neige avec le sucre et incorpore-les délicatement au chocolat.","timer":null},{"text":"Trempe rapidement les biscuits dans le lait et tapisse un moule.","timer":null},{"text":"Verse la mousse et couvre de biscuits.","timer":null},{"text":"Laisse prendre 6 h au frais avant de démouler.","timer":null}],"dessert":true,"variant":"Chocolat","change":"Avec une mousse au chocolat."}]$r$::jsonb, 'claude')
