insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pavlova', 'Pavlova', array['pavlova aux fruit', 'meringue aux fruit']::text[], 'dish', $r$[{"title":"Pavlova aux fruits rouges","intro":"Une meringue croustillante et moelleuse, avec chantilly et fruits rouges.","minutes":150,"calories":300,"difficulty":"Moyen","imageSearch":"berry pavlova","veg":true,"oven":true,"cold":false,"missing":"","origin":"Dessert australien","serves":4,"items":[{"name":"blanc d'œuf","plural":"blancs d'œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":200,"unit":"g","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à c.","have":false},{"name":"vinaigre blanc","plural":"vinaigre blanc","qty":1,"unit":"c. à c.","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":30,"unit":"cl","have":false},{"name":"fruits rouges","plural":"fruits rouges","qty":300,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 120 °C.","timer":null},{"text":"Monte les blancs en neige, puis ajoute le sucre petit à petit jusqu'à une meringue brillante.","timer":null},{"text":"Ajoute la fécule et le vinaigre, et forme un grand disque sur une plaque.","timer":null},{"text":"Enfourne 1 h 30, puis laisse refroidir dans le four éteint.","timer":{"label":"Four","min":90}},{"text":"Fouette la crème en chantilly, étale-la sur la meringue et garnis de fruits.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Pavlova exotique","intro":"La pavlova aux fruits exotiques, fraîche et acidulée.","minutes":150,"calories":300,"difficulty":"Moyen","imageSearch":"tropical pavlova","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc d'œuf","plural":"blancs d'œufs","qty":4,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":200,"unit":"g","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à c.","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":30,"unit":"cl","have":false},{"name":"mangue","plural":"mangues","qty":1,"unit":"","have":false},{"name":"kiwi","plural":"kiwis","qty":2,"unit":"","have":false},{"name":"fruit de la passion","plural":"fruits de la passion","qty":2,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 120 °C. Monte les blancs avec le sucre en meringue brillante, puis ajoute la fécule.","timer":null},{"text":"Forme un disque sur une plaque et enfourne 1 h 30.","timer":{"label":"Four","min":90}},{"text":"Laisse refroidir dans le four éteint.","timer":null},{"text":"Couvre de chantilly, de mangue et de kiwi en dés, puis de pulpe de passion.","timer":null}],"dessert":true,"variant":"Exotique","change":"Avec mangue, kiwi et fruit de la passion."},{"title":"Mini pavlovas aux fraises","intro":"Des petites pavlovas aux fraises, à servir à l'assiette.","minutes":110,"calories":280,"difficulty":"Moyen","imageSearch":"mini strawberry pavlovas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc d'œuf","plural":"blancs d'œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":150,"unit":"g","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à c.","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":25,"unit":"cl","have":false},{"name":"fraise","plural":"fraises","qty":300,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 120 °C. Monte les blancs avec le sucre en meringue, puis ajoute la fécule.","timer":null},{"text":"Forme 6 petits nids sur une plaque.","timer":null},{"text":"Enfourne 1 h et laisse refroidir dans le four.","timer":{"label":"Four","min":60}},{"text":"Garnis de chantilly et de fraises coupées.","timer":null}],"dessert":true,"variant":"Individuelles","change":"En petites meringues individuelles."}]$r$::jsonb, 'claude')
