insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('galette des roi', 'Galette des rois', array['galette frangipane', 'galette des roi frangipane', 'frangipane']::text[], 'dish', $r$[{"title":"Galette des rois à la frangipane","intro":"La galette feuilletée à la frangipane, sans oublier la fève.","minutes":60,"calories":480,"difficulty":"Moyen","imageSearch":"galette des rois","veg":true,"oven":true,"cold":false,"missing":"","origin":"Tradition française","serves":4,"items":[{"name":"pâte feuilletée","plural":"pâtes feuilletées","qty":2,"unit":"","have":false},{"name":"poudre d'amande","plural":"poudre d'amande","qty":125,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":80,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Mélange la poudre d'amande, le sucre, le beurre mou et 2 œufs.","timer":null},{"text":"Étale une pâte sur une plaque, garnis de frangipane en laissant 2 cm au bord, et pose la fève.","timer":null},{"text":"Couvre de la seconde pâte et soude bien les bords.","timer":null},{"text":"Dore au dernier œuf battu et dessine des motifs à la pointe d'un couteau.","timer":null},{"text":"Enfourne 30 min.","timer":{"label":"Four","min":30}}],"dessert":true,"variant":"La classique","change":""},{"title":"Galette des rois aux pommes","intro":"Une galette plus légère, garnie de pommes.","minutes":60,"calories":380,"difficulty":"Moyen","imageSearch":"apple galette des rois","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte feuilletée","plural":"pâtes feuilletées","qty":2,"unit":"","have":false},{"name":"pomme","plural":"pommes","qty":3,"unit":"","have":false},{"name":"compote de pommes","plural":"compote de pommes","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":30,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Étale une pâte, garnis de compote, puis de pommes en lamelles saupoudrées de sucre, et pose la fève.","timer":null},{"text":"Couvre de la seconde pâte et soude les bords.","timer":null},{"text":"Dore à l'œuf battu et enfourne 30 min.","timer":{"label":"Four","min":30}}],"dessert":true,"variant":"Aux pommes","change":"Une compote et des pommes à la place de la frangipane."},{"title":"Galette des rois chocolat-poire","intro":"Le duo poire chocolat, dans une galette des rois.","minutes":60,"calories":520,"difficulty":"Moyen","imageSearch":"chocolate pear galette","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte feuilletée","plural":"pâtes feuilletées","qty":2,"unit":"","have":false},{"name":"poudre d'amande","plural":"poudre d'amande","qty":100,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"beurre mou","plural":"beurre mou","qty":80,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":80,"unit":"g","have":false},{"name":"poire","plural":"poires","qty":2,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais fondre le chocolat.","timer":null},{"text":"Mélange la poudre d'amande, le sucre, le beurre, 2 œufs et le chocolat fondu.","timer":null},{"text":"Étale une pâte, garnis de frangipane et de poires en dés, et pose la fève.","timer":null},{"text":"Couvre de la seconde pâte, soude les bords et dore au dernier œuf.","timer":null},{"text":"Enfourne 30 min.","timer":{"label":"Four","min":30}}],"dessert":true,"variant":"Chocolat et poire","change":"Frangipane au chocolat et morceaux de poire."}]$r$::jsonb, 'claude')
