nichon","plural":"cornichons","qty":8,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min à l'eau salée, puis coupe-les en dés.","timer":{"label":"Cuisson","min":20}},{"text":"Fais cuire les œufs 10 min et coupe-les.","timer":{"label":"Cuisson","min":10}},{"text":"Coupe le jambon, les tomates et les cornichons en dés.","timer":null},{"text":"Mélange tout avec la mayonnaise et garde au frais.","timer":null}],"kids":true,"variant":"Piémontaise","change":"Avec jambon, œufs, tomates, cornichons et mayonnaise."},{"title":"Salade de pommes de terre aux lardons","intro":"Une salade de pommes de terre tiède à l'allemande.","minutes":30,"calories":420,"difficulty":"Facile","imageSearch":"german potato salad bacon","veg":false,"oven":false,"cold":false,"missing":"","origin":"Inspiration allemande","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"lardon","plural":"lardons","qty":150,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"vinaigre","plural":"vinaigre","qty":3,"unit":"c. à s.","have":false},{"name":"huile","plural":"huile","qty":2,"unit":"c. à s.","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à c.","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min à l'eau salée, puis coupe-les en rondelles.","timer":{"label":"Cuisson","min":20}},{"text":"Fais dorer les lardons et l'oignon émincé.","timer":{"label":"Poêle","min":6}},{"text":"Déglace la poêle avec le vinaigre, puis ajoute l'huile et la moutarde.","timer":null},{"text":"Verse sur les pommes de terre tièdes et parsème de ciboulette.","timer":null}],"variant":"Aux lardons","change":"Avec des lardons poêlés et des oignons."}]$r$::jsonb, 'claude')
