insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('guacamole', 'Guacamole', array['guacamole maison', 'guaca']::text[], 'dish', $r$[{"title":"Guacamole","intro":"L'avocat écrasé au citron vert, avec tomate, oignon et coriandre.","minutes":10,"calories":180,"difficulty":"Facile","imageSearch":"guacamole","veg":true,"oven":false,"cold":true,"missing":"","origin":"Recette mexicaine","serves":4,"items":[{"name":"avocat","plural":"avocats","qty":3,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Écrase la chair des avocats à la fourchette avec le jus du citron vert.","timer":null},{"text":"Ajoute la tomate en petits dés et l'oignon haché fin.","timer":null},{"text":"Ajoute la coriandre ciselée et un peu de piment.","timer":null},{"text":"Sale, mélange et sers tout de suite avec des chips de maïs.","timer":null}],"variant":"La classique","change":""},{"title":"Guacamole à la mangue","intro":"Un guacamole sucré-salé, frais et coloré.","minutes":10,"calories":190,"difficulty":"Facile","imageSearch":"mango guacamole","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"avocat","plural":"avocats","qty":2,"unit":"","have":false},{"name":"mangue","plural":"mangues","qty":1,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Écrase les avocats avec le jus du citron vert.","timer":null},{"text":"Ajoute la mangue en petits dés et l'oignon haché.","timer":null},{"text":"Ajoute la coriandre ciselée et sale.","timer":null},{"text":"Mélange et sers frais.","timer":null}],"variant":"Mangue","change":"Avec de la mangue en dés."},{"title":"Guacamole aux petits pois","intro":"Un guacamole plus léger et tout aussi vert.","minutes":15,"calories":120,"difficulty":"Facile","imageSearch":"pea guacamole","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"petits pois surgelés","plural":"petits pois surgelés","qty":200,"unit":"g","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les petits pois 5 min et rafraîchis-les.","timer":{"label":"Cuisson","min":5}},{"text":"Mixe-les grossièrement avec l'avocat et le jus du citron vert.","timer":null},{"text":"Ajoute l'oignon haché et la coriandre.","timer":null},{"text":"Sale et sers frais.","timer":null}],"variant":"Plus léger","change":"La moitié des avocats est remplacée par des petits pois."}]$r$::jsonb, 'claude')
