insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tzatziki', 'Tzatziki', array['tzaziki', 'sauce concombre yaourt', 'concombre au yaourt']::text[], 'dish', $r$[{"title":"Tzatziki","intro":"Le yaourt grec au concombre, à l'ail et à l'aneth, pour l'apéritif ou les grillades.","minutes":15,"calories":110,"difficulty":"Facile","imageSearch":"tzatziki","veg":true,"oven":false,"cold":true,"missing":"","origin":"Recette grecque","serves":4,"items":[{"name":"yaourt grec","plural":"yaourts grecs","qty":2,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Râpe le concombre, sale-le et laisse-le dégorger 10 min.","timer":null},{"text":"Presse-le bien dans tes mains pour retirer l'eau.","timer":null},{"text":"Mélange-le avec le yaourt, l'ail écrasé, l'aneth et le jus du citron.","timer":null},{"text":"Arrose d'un filet d'huile d'olive et garde au frais.","timer":null}],"variant":"La classique","change":""},{"title":"Tzatziki à la menthe","intro":"Un tzatziki tout frais à la menthe.","minutes":15,"calories":110,"difficulty":"Facile","imageSearch":"mint tzatziki","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"yaourt grec","plural":"yaourts grecs","qty":2,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"menthe fraîche","plural":"menthe fraîche","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Râpe le concombre, sale-le et presse-le pour retirer l'eau.","timer":null},{"text":"Mélange-le avec le yaourt et l'ail écrasé.","timer":null},{"text":"Ajoute la menthe ciselée et le jus du citron.","timer":null},{"text":"Garde au frais jusqu'au service.","timer":null}],"variant":"Menthe","change":"La menthe remplace l'aneth."},{"title":"Tzatziki de betterave","intro":"Une version colorée du tzatziki, à la betterave.","minutes":15,"calories":120,"difficulty":"Facile","imageSearch":"beet tzatziki","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"yaourt grec","plural":"yaourts grecs","qty":2,"unit":"","have":false},{"name":"betterave cuite","plural":"betteraves cuites","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Râpe la betterave.","timer":null},{"text":"Mélange-la au yaourt avec l'ail écrasé.","timer":null},{"text":"Ajoute l'aneth ciselé et le jus du citron, puis sale.","timer":null},{"text":"Garde au frais.","timer":null}],"variant":"Betterave","change":"Avec de la betterave râpée, tout rose."}]$r$::jsonb, 'claude')
