insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('nem', 'Nems', array['nem au porc', 'nem maison']::text[], 'dish', $r$[{"title":"Nems au porc","intro":"Les rouleaux frits croustillants farcis au porc, aux vermicelles et aux champignons noirs.","minutes":60,"calories":350,"difficulty":"Difficile","imageSearch":"vietnamese spring rolls nem","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette vietnamienne","serves":4,"items":[{"name":"galettes de riz","plural":"galettes de riz","qty":16,"unit":"","have":false},{"name":"porc haché","plural":"porc haché","qty":300,"unit":"g","have":false},{"name":"vermicelles de riz","plural":"vermicelles de riz","qty":50,"unit":"g","have":false},{"name":"champignons noirs séchés","plural":"champignons noirs séchés","qty":10,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"sauce nuoc-mâm","plural":"sauce nuoc-mâm","qty":2,"unit":"c. à s.","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false},{"name":"salade verte","plural":"salade verte","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais tremper les vermicelles et les champignons 10 min dans l'eau chaude, puis coupe-les.","timer":null},{"text":"Mélange le porc, les vermicelles, les champignons, la carotte râpée, l'œuf et le nuoc-mâm.","timer":null},{"text":"Humidifie une galette, pose une cuillerée de farce, replie les bords et roule serré.","timer":null},{"text":"Fais frire les nems 6 min dans l'huile chaude, jusqu'à ce qu'ils soient dorés.","timer":{"label":"Friture","min":6}},{"text":"Sers avec des feuilles de salade, de la menthe et de la sauce nuoc-mâm.","timer":null}],"variant":"La classique","change":""},{"title":"Nems au poulet","intro":"Des nems croustillants farcis au poulet.","minutes":60,"calories":330,"difficulty":"Difficile","imageSearch":"chicken spring rolls","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"galettes de riz","plural":"galettes de riz","qty":16,"unit":"","have":false},{"name":"poulet haché","plural":"poulet haché","qty":300,"unit":"g","have":false},{"name":"vermicelles de riz","plural":"vermicelles de riz","qty":50,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Fais tremper les vermicelles 10 min dans l'eau chaude, puis coupe-les.","timer":null},{"text":"Mélange le poulet, les vermicelles, la carotte râpée, l'oignon haché, l'œuf et la sauce soja.","timer":null},{"text":"Roule la farce dans les galettes humidifiées.","timer":null},{"text":"Fais frire 6 min dans l'huile chaude.","timer":{"label":"Friture","min":6}}],"variant":"Au poulet","change":"Le poulet remplace le porc."},{"title":"Nems aux légumes au four","intro":"Des nems plus légers, aux légumes et sans friture.","minutes":50,"calories":220,"difficulty":"Moyen","imageSearch":"baked vegetable spring rolls","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"galettes de riz","plural":"galettes de riz","qty":16,"unit":"","have":false},{"name":"vermicelles de riz","plural":"vermicelles de riz","qty":50,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"chou chinois","plural":"choux chinois","qty":0.25,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"huile","plural":"huile","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais tremper les vermicelles et coupe-les.","timer":null},{"text":"Fais revenir les carottes râpées, le chou et les champignons émincés 5 min avec la sauce soja.","timer":{"label":"Poêle","min":5}},{"text":"Mélange avec les vermicelles et roule la farce dans les galettes humidifiées.","timer":null},{"text":"Badigeonne d'huile et enfourne 20 min en les retournant.","timer":{"label":"Four","min":20}}],"variant":"Végétariens au four","change":"Farcis aux légumes et cuits au four."}]$r$::jsonb, 'claude')
