insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('rouleau de printemp', 'Rouleaux de printemps', array['rouleau printemp', 'spring roll']::text[], 'dish', $r$[{"title":"Rouleaux de printemps aux crevettes","intro":"Des galettes de riz roulées avec crevettes, vermicelles, salade et menthe, sans cuisson.","minutes":30,"calories":220,"difficulty":"Moyen","imageSearch":"fresh spring rolls shrimp","veg":false,"oven":false,"cold":true,"missing":"","origin":"Recette vietnamienne","serves":4,"items":[{"name":"galettes de riz","plural":"galettes de riz","qty":8,"unit":"","have":false},{"name":"crevette cuite","plural":"crevettes cuites","qty":16,"unit":"","have":false},{"name":"vermicelles de riz","plural":"vermicelles de riz","qty":80,"unit":"g","have":false},{"name":"salade verte","plural":"salade verte","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"menthe fraîche","plural":"menthe fraîche","qty":null,"unit":"","have":false},{"name":"sauce hoisin","plural":"sauce hoisin","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais tremper les vermicelles 5 min dans l'eau chaude et égoutte-les.","timer":null},{"text":"Râpe la carotte et décortique les crevettes.","timer":null},{"text":"Trempe une galette quelques secondes dans l'eau tiède et pose-la à plat.","timer":null},{"text":"Garnis de salade, vermicelles, carotte et menthe, puis de 2 crevettes coupées en deux.","timer":null},{"text":"Replie les côtés et roule serré. Sers avec la sauce hoisin.","timer":null}],"variant":"La classique","change":""},{"title":"Rouleaux de printemps au tofu","intro":"Des rouleaux frais végétariens, au tofu doré.","minutes":30,"calories":210,"difficulty":"Moyen","imageSearch":"tofu fresh spring rolls","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"galettes de riz","plural":"galettes de riz","qty":8,"unit":"","have":false},{"name":"tofu ferme","plural":"tofu ferme","qty":200,"unit":"g","have":false},{"name":"vermicelles de riz","plural":"vermicelles de riz","qty":80,"unit":"g","have":false},{"name":"salade verte","plural":"salade verte","qty":1,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"menthe fraîche","plural":"menthe fraîche","qty":null,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Coupe le tofu en bâtonnets et fais-le dorer avec 1 c. à s. de sauce soja.","timer":{"label":"Poêle","min":6}},{"text":"Fais tremper les vermicelles et coupe le concombre en bâtonnets.","timer":null},{"text":"Trempe une galette dans l'eau tiède, garnis de salade, vermicelles, concombre, menthe et tofu.","timer":null},{"text":"Roule serré et sers avec le reste de la sauce soja.","timer":null}],"variant":"Végétariens","change":"Avec du tofu grillé à la place des crevettes."},{"title":"Rouleaux de printemps au poulet","intro":"Des rouleaux frais au poulet, avec une sauce cacahuète.","minutes":35,"calories":280,"difficulty":"Moyen","imageSearch":"chicken fresh spring rolls peanut sauce","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"galettes de riz","plural":"galettes de riz","qty":8,"unit":"","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"vermicelles de riz","plural":"vermicelles de riz","qty":80,"unit":"g","have":false},{"name":"salade verte","plural":"salade verte","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"beurre de cacahuète","plural":"beurre de cacahuète","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le poulet 10 min à la poêle et coupe-le en lamelles.","timer":{"label":"Poêle","min":10}},{"text":"Fais tremper les vermicelles et râpe la carotte.","timer":null},{"text":"Roule salade, vermicelles, carotte et poulet dans les galettes humidifiées.","timer":null},{"text":"Mélange le beurre de cacahuète, la sauce soja et 3 c. à s. d'eau chaude pour la sauce.","timer":null}],"variant":"Au poulet","change":"Avec du poulet et une sauce aux cacahuètes."}]$r$::jsonb, 'claude')
