insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('samoussa', 'Samoussas', array['samosa']::text[], 'dish', $r$[{"title":"Samoussas au bœuf","intro":"Des triangles croustillants farcis au bœuf haché épicé et aux petits pois.","minutes":50,"calories":300,"difficulty":"Moyen","imageSearch":"beef samosas","veg":false,"oven":true,"cold":false,"missing":"","origin":"Inspiration indienne et réunionnaise","serves":4,"items":[{"name":"feuilles de brick","plural":"feuilles de brick","qty":8,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":300,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"petits pois surgelés","plural":"petits pois surgelés","qty":100,"unit":"g","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"huile","plural":"huile","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Fais revenir l'oignon, puis le bœuf et le curry 8 min. Ajoute les petits pois et la coriandre.","timer":{"label":"Poêle","min":8}},{"text":"Coupe les feuilles de brick en deux et plie chaque bande en triangle autour d'une cuillerée de farce.","timer":null},{"text":"Badigeonne d'huile et enfourne 15 min.","timer":{"label":"Four","min":15}}],"variant":"La classique","change":""},{"title":"Samoussas aux légumes","intro":"Des samoussas végétariens, à la farce épicée.","minutes":50,"calories":240,"difficulty":"Moyen","imageSearch":"vegetable samosas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"feuilles de brick","plural":"feuilles de brick","qty":8,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":3,"unit":"","have":false},{"name":"petits pois surgelés","plural":"petits pois surgelés","qty":150,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"huile","plural":"huile","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire les pommes de terre en dés 10 min à l'eau.","timer":{"label":"Cuisson","min":10}},{"text":"Fais revenir l'oignon avec le curry, puis ajoute les pommes de terre et les petits pois.","timer":null},{"text":"Plie la farce en triangles dans les bandes de brick.","timer":null},{"text":"Badigeonne d'huile et enfourne 15 min à 200 °C.","timer":{"label":"Four","min":15}}],"variant":"Végétariens","change":"Farcis de pommes de terre et de petits pois au curry."},{"title":"Samoussas au thon","intro":"Des samoussas faciles au thon, pour l'apéritif.","minutes":35,"calories":260,"difficulty":"Facile","imageSearch":"tuna samosas","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"feuilles de brick","plural":"feuilles de brick","qty":8,"unit":"","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"fromage frais","plural":"fromage frais","qty":100,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"huile","plural":"huile","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Mélange le thon émietté, le fromage frais, l'oignon haché et le persil.","timer":null},{"text":"Plie la farce en triangles dans les bandes de brick.","timer":null},{"text":"Badigeonne d'huile et enfourne 12 min.","timer":{"label":"Four","min":12}}],"variant":"Au thon","change":"Farcis au thon, à l'oignon et au fromage frais."}]$r$::jsonb, 'claude')
