insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('accra de morue', 'Accras de morue', array['accra', 'acra de morue']::text[], 'dish', $r$[{"title":"Accras de morue","intro":"Les beignets antillais à la morue, relevés au piment et à la cive.","minutes":120,"calories":280,"difficulty":"Moyen","imageSearch":"salt cod fritters accras","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette antillaise","serves":4,"items":[{"name":"morue salée","plural":"morue salée","qty":250,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Fais dessaler la morue 1 nuit dans l'eau froide en changeant l'eau.","timer":null},{"text":"Poche-la 10 min dans de l'eau frémissante, puis émiette-la.","timer":{"label":"Cuisson","min":10}},{"text":"Mélange la farine, la levure, l'œuf et 20 cl d'eau, puis ajoute la morue, l'oignon, l'ail et le piment hachés.","timer":null},{"text":"Laisse reposer 1 h.","timer":{"label":"Repos","min":60}},{"text":"Fais frire des petites cuillerées de pâte 3 min dans l'huile chaude.","timer":{"label":"Friture","min":3}}],"variant":"La classique","change":""},{"title":"Accras de crevettes","intro":"Des accras plus rapides, aux crevettes.","minutes":45,"calories":270,"difficulty":"Moyen","imageSearch":"shrimp fritters","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"crevette décortiquée","plural":"crevettes décortiquées","qty":250,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Coupe les crevettes en petits morceaux.","timer":null},{"text":"Mélange la farine, la levure, l'œuf et 20 cl d'eau.","timer":null},{"text":"Ajoute les crevettes, l'oignon, l'ail et le piment hachés. Laisse reposer 30 min.","timer":{"label":"Repos","min":30}},{"text":"Fais frire des petites cuillerées de pâte 3 min.","timer":{"label":"Friture","min":3}}],"variant":"Crevettes","change":"Les crevettes remplacent la morue."},{"title":"Accras de légumes","intro":"Des accras végétariens à la courgette et à la carotte.","minutes":40,"calories":230,"difficulty":"Facile","imageSearch":"vegetable fritters","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"farine","plural":"farines","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Râpe la courgette et la carotte, et presse-les pour retirer l'eau.","timer":null},{"text":"Mélange la farine, la levure, l'œuf et 15 cl d'eau, puis les légumes et l'oignon haché.","timer":null},{"text":"Sale et poivre.","timer":null},{"text":"Fais frire des petites cuillerées de pâte 3 min.","timer":{"label":"Friture","min":3}}],"variant":"Végétariens","change":"Avec des légumes râpés à la place du poisson."}]$r$::jsonb, 'claude')
