insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gougere', 'Gougères', array['gougere au fromage', 'chou au fromage']::text[], 'dish', $r$[{"title":"Gougères au comté","intro":"Des petits choux au fromage, dorés et moelleux, pour l'apéritif.","minutes":50,"calories":180,"difficulty":"Moyen","imageSearch":"gougeres cheese puffs","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité bourguignonne","serves":4,"items":[{"name":"farine","plural":"farines","qty":100,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":70,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"comté râpé","plural":"comté râpé","qty":100,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Porte à ébullition 15 cl d'eau, le beurre et une pincée de sel.","timer":null},{"text":"Verse la farine d'un coup et remue jusqu'à ce que la pâte se détache.","timer":null},{"text":"Hors du feu, ajoute les œufs un à un, puis les trois quarts du comté et du poivre.","timer":null},{"text":"Forme des petits tas sur une plaque, parsème du reste de comté.","timer":null},{"text":"Enfourne 20 min sans ouvrir le four.","timer":{"label":"Four","min":20}}],"variant":"La classique","change":""},{"title":"Gougères au jambon","intro":"Des gougères plus gourmandes, au fromage et au jambon.","minutes":50,"calories":200,"difficulty":"Moyen","imageSearch":"ham cheese puffs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":100,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":70,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":2,"unit":"tranches","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C et prépare la pâte à choux : eau, beurre et sel à ébullition, puis la farine et les œufs un à un.","timer":null},{"text":"Ajoute l'emmental et le jambon en petits dés.","timer":null},{"text":"Forme des petits tas sur une plaque.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"variant":"Au jambon","change":"Avec du jambon en petits dés dans la pâte."},{"title":"Gougères aux herbes","intro":"Des gougères parfumées aux herbes fraîches.","minutes":50,"calories":175,"difficulty":"Moyen","imageSearch":"herb cheese puffs","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":100,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":70,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":60,"unit":"g","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C et prépare la pâte à choux.","timer":null},{"text":"Ajoute le parmesan râpé et la ciboulette ciselée.","timer":null},{"text":"Forme des petits tas sur une plaque.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"variant":"Aux herbes","change":"Avec de la ciboulette et du parmesan."}]$r$::jsonb, 'claude')
