insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('soupe miso', 'Soupe miso', array['miso', 'soupe au miso', 'miso soup']::text[], 'dish', $r$[{"title":"Soupe miso au tofu","intro":"Le bouillon japonais au miso, avec tofu, algues et oignon nouveau.","minutes":15,"calories":120,"difficulty":"Facile","imageSearch":"miso soup tofu","veg":true,"oven":false,"cold":false,"missing":"","origin":"Recette japonaise","serves":4,"items":[{"name":"pâte de miso","plural":"pâte de miso","qty":4,"unit":"c. à s.","have":false},{"name":"tofu soyeux","plural":"tofu soyeux","qty":200,"unit":"g","have":false},{"name":"algues wakamé","plural":"algues wakamé","qty":5,"unit":"g","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false}],"steps":[{"text":"Fais tremper les algues 5 min dans l'eau froide.","timer":null},{"text":"Porte 1 litre d'eau à frémissement, sans faire bouillir.","timer":null},{"text":"Délaye le miso dans une louche d'eau chaude et verse-le dans la casserole.","timer":null},{"text":"Ajoute le tofu en dés, les algues égouttées et l'oignon émincé.","timer":null},{"text":"Sers tout de suite, sans faire bouillir le miso.","timer":null}],"variant":"La classique","change":""},{"title":"Soupe miso aux nouilles","intro":"Une soupe miso complète, avec des nouilles udon.","minutes":20,"calories":350,"difficulty":"Facile","imageSearch":"miso noodle soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte de miso","plural":"pâte de miso","qty":4,"unit":"c. à s.","have":false},{"name":"nouilles udon","plural":"nouilles udon","qty":400,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":100,"unit":"g","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false}],"steps":[{"text":"Porte 1,2 litre d'eau à frémissement avec les champignons émincés.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les nouilles et laisse cuire selon le paquet.","timer":null},{"text":"Délaye le miso dans une louche de bouillon et ajoute-le.","timer":null},{"text":"Ajoute les épinards et l'oignon émincé, et sers aussitôt.","timer":null}],"variant":"Aux nouilles","change":"Avec des nouilles et des champignons pour en faire un repas."},{"title":"Soupe miso au saumon","intro":"Une soupe miso plus consistante, au saumon.","minutes":20,"calories":230,"difficulty":"Facile","imageSearch":"salmon miso soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte de miso","plural":"pâte de miso","qty":4,"unit":"c. à s.","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":2,"unit":"","have":false},{"name":"tofu soyeux","plural":"tofu soyeux","qty":150,"unit":"g","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"algues wakamé","plural":"algues wakamé","qty":5,"unit":"g","have":false}],"steps":[{"text":"Fais tremper les algues 5 min.","timer":null},{"text":"Porte 1 litre d'eau à frémissement et poche le saumon en dés 4 min.","timer":{"label":"Cuisson","min":4}},{"text":"Délaye le miso dans une louche de bouillon et ajoute-le.","timer":null},{"text":"Ajoute le tofu, les algues et l'oignon, puis sers.","timer":null}],"variant":"Au saumon","change":"Avec des dés de saumon pochés dans le bouillon."}]$r$::jsonb, 'claude')
