insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('veloute de brocoli', 'Velouté de brocoli', array['soupe de brocoli', 'veloute brocoli', 'creme de brocoli']::text[], 'dish', $r$[{"title":"Velouté de brocoli","intro":"Un velouté tout vert et doux, avec une pomme de terre pour l'onctuosité.","minutes":30,"calories":150,"difficulty":"Facile","imageSearch":"broccoli soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir l'oignon émincé dans une casserole.","timer":null},{"text":"Ajoute le brocoli en fleurettes, la pomme de terre en dés, le bouillon et 80 cl d'eau.","timer":null},{"text":"Laisse cuire 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Mixe avec la crème, sale et poivre.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Velouté de brocoli au fromage","intro":"Le velouté de brocoli crémeux au cheddar, qui plaît aux enfants.","minutes":30,"calories":250,"difficulty":"Facile","imageSearch":"broccoli cheddar soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":100,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Fais revenir l'oignon, ajoute le brocoli, la pomme de terre, le bouillon et 60 cl d'eau.","timer":null},{"text":"Laisse cuire 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Mixe avec le lait.","timer":null},{"text":"Ajoute le cheddar et remue jusqu'à ce qu'il fonde.","timer":null}],"kids":true,"variant":"Au fromage","change":"Avec du cheddar fondu."},{"title":"Velouté brocoli et lait de coco","intro":"Un velouté vegan parfumé au gingembre et au lait de coco.","minutes":30,"calories":200,"difficulty":"Facile","imageSearch":"broccoli coconut soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"lait de coco","plural":"lait de coco","qty":20,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et le gingembre.","timer":null},{"text":"Ajoute le brocoli, le bouillon et 70 cl d'eau, et laisse cuire 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Mixe avec le lait de coco.","timer":null},{"text":"Sale et poivre.","timer":null}],"variant":"Coco","change":"Avec du lait de coco et du gingembre."}]$r$::jsonb, 'claude')
