insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('soupe de poi casse', 'Soupe de pois cassés', array['poi casse', 'veloute de poi casse', 'puree de poi casse']::text[], 'dish', $r$[{"title":"Soupe de pois cassés","intro":"La soupe d'hiver épaisse et réconfortante, avec des lardons dorés.","minutes":70,"calories":380,"difficulty":"Facile","imageSearch":"split pea soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pois cassés","plural":"pois cassés","qty":300,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":150,"unit":"g","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Rince les pois cassés.","timer":null},{"text":"Fais revenir l'oignon et les carottes en rondelles.","timer":null},{"text":"Ajoute les pois, le bouillon et 1,2 litre d'eau, et laisse cuire 50 min.","timer":{"label":"Cuisson","min":50}},{"text":"Mixe avec la crème.","timer":null},{"text":"Fais dorer les lardons et parsème-les sur la soupe.","timer":{"label":"Poêle","min":5}}],"variant":"La classique","change":""},{"title":"Soupe de pois cassés végétarienne","intro":"Une soupe de pois cassés vegan, parfumée au cumin.","minutes":65,"calories":300,"difficulty":"Facile","imageSearch":"vegan split pea soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pois cassés","plural":"pois cassés","qty":300,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir l'oignon et les carottes dans l'huile avec le cumin.","timer":null},{"text":"Ajoute les pois cassés rincés, le bouillon et 1,2 litre d'eau.","timer":null},{"text":"Laisse cuire 50 min.","timer":{"label":"Cuisson","min":50}},{"text":"Mixe, sale et poivre.","timer":null}],"variant":"Végétarienne","change":"Sans lardons, avec du cumin."},{"title":"Soupe de pois cassés au jambon","intro":"La soupe de pois cassés en plat complet.","minutes":70,"calories":400,"difficulty":"Facile","imageSearch":"split pea ham soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pois cassés","plural":"pois cassés","qty":300,"unit":"g","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"pain de mie","plural":"pains de mie","qty":2,"unit":"tranches","have":false}],"steps":[{"text":"Fais revenir l'oignon et les carottes, ajoute les pois rincés, le bouillon et 1,2 litre d'eau.","timer":null},{"text":"Laisse cuire 50 min, puis mixe.","timer":{"label":"Cuisson","min":50}},{"text":"Fais griller le pain de mie en petits croûtons.","timer":null},{"text":"Sers avec le jambon en dés et les croûtons.","timer":null}],"variant":"Au jambon","change":"Avec du jambon en dés et des croûtons."}]$r$::jsonb, 'claude')
