insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('osso buco', 'Osso buco', array['osso bucco', 'jarret de veau', 'ossobuco']::text[], 'dish', $r$[{"title":"Osso buco à la milanaise","intro":"Des tranches de jarret de veau mijotées à la tomate, avec une gremolata au citron.","minutes":135,"calories":480,"difficulty":"Moyen","imageSearch":"osso buco","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"jarret de veau","plural":"jarrets de veau","qty":4,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"céleri","plural":"céleris","qty":1,"unit":"","have":false},{"name":"vin blanc","plural":"vin blanc","qty":15,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":2,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false}],"steps":[{"text":"Farine légèrement les tranches de veau et fais-les dorer dans une cocotte huilée.","timer":{"label":"Cuisson","min":8}},{"text":"Retire-les et fais revenir l'oignon, les carottes et le céleri en dés.","timer":null},{"text":"Remets la viande, ajoute le vin, les tomates et 20 cl d'eau.","timer":null},{"text":"Couvre et laisse mijoter 1 h 45 à feu doux.","timer":{"label":"Cuisson","min":105}},{"text":"Hache le persil avec l'ail et le zeste du citron : c'est la gremolata.","timer":null},{"text":"Parsème la gremolata sur l'osso buco au moment de servir.","timer":null}],"variant":"La classique","change":""},{"title":"Osso buco de dinde","intro":"L'osso buco en version dinde, mijotée à la tomate.","minutes":85,"calories":380,"difficulty":"Facile","imageSearch":"turkey osso buco","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"osso buco de dinde","plural":"osso buco de dinde","qty":4,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer la dinde dans une cocotte huilée.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute l'oignon et les carottes en dés et fais revenir 3 min.","timer":null},{"text":"Ajoute le vin, les tomates et 15 cl d'eau.","timer":null},{"text":"Couvre et laisse mijoter 1 h.","timer":{"label":"Cuisson","min":60}},{"text":"Parsème de persil haché et de zeste de citron.","timer":null}],"variant":"De dinde","change":"Avec de l'osso buco de dinde, plus rapide et moins cher."},{"title":"Osso buco en blanc","intro":"L'osso buco à l'ancienne, en sauce blanche au citron.","minutes":135,"calories":450,"difficulty":"Moyen","imageSearch":"osso buco bianco","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"jarret de veau","plural":"jarrets de veau","qty":4,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vin blanc","qty":25,"unit":"cl","have":false},{"name":"bouillon de volaille","plural":"bouillon de volaille","qty":1,"unit":"","have":false},{"name":"farine","plural":"farines","qty":2,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Farine le veau et fais-le dorer dans une cocotte.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute l'oignon et les carottes, puis le vin, le bouillon et 20 cl d'eau.","timer":null},{"text":"Couvre et laisse mijoter 1 h 45.","timer":{"label":"Cuisson","min":105}},{"text":"Ajoute le zeste et le jus du citron et le persil haché avant de servir.","timer":null}],"variant":"Sans tomate","change":"Mijoté au vin blanc et au bouillon, sans tomate."}]$r$::jsonb, 'claude')
