insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('magret de canard', 'Magret de canard', array['magret', 'magret poele']::text[], 'dish', $r$[{"title":"Magret de canard poêlé","intro":"Le magret saisi côté peau, rosé à cœur, avec des pommes de terre sautées dans sa graisse.","minutes":40,"calories":650,"difficulty":"Moyen","imageSearch":"seared duck breast","veg":false,"oven":false,"cold":false,"missing":"","origin":"Sud-Ouest","serves":4,"items":[{"name":"magret de canard","plural":"magrets de canard","qty":2,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Quadrille la peau des magrets sans couper la chair.","timer":null},{"text":"Fais-les cuire côté peau 8 min à feu moyen, en retirant la graisse.","timer":{"label":"Poêle","min":8}},{"text":"Retourne-les 4 min, puis laisse reposer 5 min sous du papier aluminium.","timer":{"label":"Poêle","min":4}},{"text":"Fais sauter les pommes de terre en dés dans la graisse 20 min.","timer":{"label":"Poêle","min":20}},{"text":"Ajoute l'ail et le persil hachés, et sers avec le magret en tranches.","timer":null}],"variant":"La classique","change":""},{"title":"Magret de canard au miel","intro":"Le magret sucré-salé, laqué au miel.","minutes":30,"calories":600,"difficulty":"Moyen","imageSearch":"honey glazed duck breast","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"magret de canard","plural":"magrets de canard","qty":2,"unit":"","have":false},{"name":"miel","plural":"miels","qty":3,"unit":"c. à s.","have":false},{"name":"vinaigre balsamique","plural":"vinaigre balsamique","qty":2,"unit":"c. à s.","ha