insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet au citron', 'Poulet au citron', array['poulet citron', 'poulet au citron confit']::text[], 'dish', $r$[{"title":"Poulet au citron et au thym","intro":"Des cuisses de poulet rôties au citron, à l'ail et au thym.","minutes":60,"calories":450,"difficulty":"Facile","imageSearch":"lemon chicken thighs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":4,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":4,"unit":"gousse","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":600,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Coupe les pommes de terre en quartiers et un citron en rondelles.","timer":null},{"text":"Mets tout dans un plat avec le poulet, l'ail, le thym, l'huile et le jus de l'autre citron.","timer":null},{"text":"Enfourne 45 min en arrosant de temps en temps.","timer":{"label":"Four","min":45}}],"variant":"La classique","change":""},{"title":"Poulet au citron à la chinoise","intro":"Le poulet au citron du restaurant chinois, croustillant et nappé.","minutes":30,"calories":480,"difficulty":"Moyen","imageSearch":"chinese lemon chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Inspiration chinoise","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":4,"unit":"c. à s.","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":1,"unit":"c. à s.","have":false},{"name":"huile","plural":"huile","qty":5,"unit":"c. à s.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe le poulet en morceaux, trempe-les dans l'œuf battu puis dans 3 c. à s. de fécule.","timer":null},{"text":"Fais-les dorer 6 min dans l'huile chaude.","timer":{"label":"Poêle","min":6}},{"text":"Chauffe le jus des citrons, le sucre, la sauce soja et le reste de fécule délayée dans 10 cl d'eau jusqu'à ce que ça épaississe.","timer":null},{"text":"Nappe le poulet de sauce et sers avec le riz.","timer":null}],"variant":"À la chinoise","change":"Des morceaux de poulet frits et une sauce au citron."},{"title":"Tajine de poulet au citron confit","intro":"Le poulet à la marocaine, fondant et parfumé.","minutes":70,"calories":430,"difficulty":"Facile","imageSearch":"chicken preserved lemon olives","veg":false,"oven":false,"cold":false,"missing":"","origin":"Inspiration marocaine","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":4,"unit":"","have":false},{"name":"citron confit","plural":"citrons confits","qty":2,"unit":"","have":false},{"name":"olives vertes","plural":"olives vertes","qty":100,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"curcuma","plural":"curcuma","qty":1,"unit":"c. à c.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet dans une cocotte huilée.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute les oignons émincés, le gingembre et le curcuma.","timer":null},{"text":"Ajoute 30 cl d'eau, couvre et laisse mijoter 40 min.","timer":{"label":"Cuisson","min":40}},{"text":"Ajoute les citrons confits en quartiers et les olives, et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Parsème de coriandre.","timer":null}],"variant":"Citron confit","change":"Mijoté aux olives et au citron confit."}]$r$::jsonb, 'claude')
