insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('rougail saucisse', 'Rougail saucisse', array['rougail', 'rougail saucisse reunionnai']::text[], 'dish', $r$[{"title":"Rougail saucisse","intro":"Le plat réunionnais : saucisses fumées mijotées dans une sauce tomate au gingembre et au piment.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"rougail saucisse","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette réunionnaise","serves":4,"items":[{"name":"saucisse fumée","plural":"saucisses fumées","qty":6,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":6,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"curcuma","plural":"curcuma","qty":1,"unit":"c. à c.","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais blanchir les saucisses 5 min à l'eau bouillante, puis coupe-les en rondelles.","timer":{"label":"Cuisson","min":5}},{"text":"Fais-les dorer dans une cocotte.","timer":null},{"text":"Ajoute les oignons émincés, l'ail, le gingembre, le curcuma et le piment.","timer":null},{"text":"Ajoute les tomates en dés et laisse mijoter 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Sers avec du riz blanc.","timer":null}],"variant":"La classique","change":""},{"title":"Rougail de crevettes","intro":"Un rougail plus léger, aux crevettes.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"shrimp rougail","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette réunionnaise","serves":4,"items":[{"name":"crevette décortiquée","plural":"crevettes décortiquées","qty":500,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":5,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"curcuma","plural":"curcuma","qty":1,"unit":"c. à c.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais revenir les oignons, l'ail, le gingembre et le curcuma.","timer":null},{"text":"Ajoute les tomates en dés et laisse mijoter 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute les crevettes et fais cuire 4 min.","timer":{"label":"Cuisson","min":4}}],"variant":"Crevettes","change":"Les crevettes remplacent les saucisses."},{"title":"Rougail de lentilles","intro":"Un rougail végétarien épicé et rassasiant.","minutes":45,"calories":380,"difficulty":"Facile","imageSearch":"lentil tomato curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lentille corail","plural":"lentilles corail","qty":250,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"curcuma","plural":"curcuma","qty":1,"unit":"c. à c.","have":false},{"name":"riz","plural":"riz","qty":200,"unit":"g","have":false}],"steps":[{"text":"Fais revenir les oignons, l'ail, le gingembre et le curcuma.","timer":null},{"text":"Ajoute les tomates en dés, les lentilles et 50 cl d'eau.","timer":null},{"text":"Laisse mijoter 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Sers avec du riz.","timer":null}],"variant":"Végétarien","change":"Des lentilles à la sauce rougail, sans viande."}]$r$::jsonb, 'claude')
