insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('colombo de poulet', 'Colombo de poulet', array['colombo', 'poulet colombo']::text[], 'dish', $r$[{"title":"Colombo de poulet","intro":"Le curry antillais au poulet, avec pommes de terre et légumes, parfumé à la poudre de colombo.","minutes":60,"calories":480,"difficulty":"Facile","imageSearch":"chicken colombo curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette antillaise","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":4,"unit":"","have":false},{"name":"poudre de colombo","plural":"poudre de colombo","qty":2,"unit":"c. à s.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false}],"steps":[{"text":"Frotte le poulet avec le jus du citron vert, l'ail et 1 c. à s. de colombo.","timer":null},{"text":"Fais-le dorer dans une cocotte avec les oignons.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute le reste du colombo, les pommes de terre et la courgette en morceaux, et 40 cl d'eau.","timer":null},{"text":"Couvre et laisse mijoter 40 min.","timer":{"label":"Cuisson","min":40}}],"variant":"La classique","change":""},{"title":"Colombo de porc","intro":"Le colombo antillais au porc, mijoté longuement.","minutes":90,"calories":560,"difficulty":"Facile","imageSearch":"pork colombo","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette antillaise","serves":4,"items":[{"name":"épaule de porc","plural":"épaules de porc","qty":800,"unit":"g","have":false},{"name":"poudre de colombo","plural":"poudre de colombo","qty":2,"unit":"c. à s.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":3,"unit":"","have":false},{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false}],"steps":[{"text":"Coupe le porc en cubes et fais-le dorer avec les oignons.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute l'ail, le colombo, puis 50 cl d'eau.","timer":null},{"text":"Laisse mijoter 45 min.","timer":{"label":"Cuisson","min":45}},{"text":"Ajoute les pommes de terre et l'aubergine en morceaux et laisse 25 min.","timer":{"label":"Cuisson","min":25}}],"variant":"Au porc","change":"Avec de l'épaule de porc."},{"title":"Colombo de légumes","intro":"Un colombo végétarien, aux légumes et pois chiches.","minutes":45,"calories":380,"difficulty":"Facile","imageSearch":"vegetable colombo curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pois chiche","plural":"pois chiches","qty":400,"unit":"g","have":false},{"name":"patate douce","plural":"patates douces","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"poudre de colombo","plural":"poudre de colombo","qty":2,"unit":"c. à s.","have":false},{"name":"lait de coco","plural":"lait de coco","qty":20,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon avec le colombo.","timer":null},{"text":"Ajoute la patate douce, la courgette et l'aubergine en dés.","timer":null},{"text":"Ajoute le lait de coco et 20 cl d'eau, et laisse mijoter 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Ajoute les pois chiches et laisse 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"Végétarien","change":"Pois chiches et légumes à la place de la viande."}]$r$::jsonb, 'claude')
