insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('navarin d agneau', 'Navarin d''agneau', array['navarin', 'ragout d agneau', 'navarin printanier']::text[], 'dish', $r$[{"title":"Navarin d'agneau printanier","intro":"Le ragoût d'agneau aux petits légumes de printemps : carottes, navets et petits pois.","minutes":120,"calories":550,"difficulty":"Moyen","imageSearch":"lamb navarin stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat français","serves":4,"items":[{"name":"épaule d'agneau","plural":"épaules d'agneau","qty":1000,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":4,"unit":"","have":false},{"name":"navet","plural":"navets","qty":4,"unit":"","have":false},{"name":"petits pois surgelés","plural":"petits pois surgelés","qty":200,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":200,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Coupe l'agneau en morceaux et fais-le dorer dans une cocotte.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute les oignons, saupoudre de farine et remue.","timer":null},{"text":"Ajoute les tomates, le bouquet garni et 50 cl d'eau, et laisse mijoter 1 h.","timer":{"label":"Cuisson","min":60}},{"text":"Ajoute les carottes et les navets en morceaux, et laisse 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Ajoute les petits pois 10 min avant la fin.","timer":{"label":"Cuisson","min":10}}],"variant":"La classique","change":""},{"title":"Navarin d'agneau aux pommes de terre","intro":"Un navarin plus familial, avec des pommes de terre.","minutes":120,"calories":580,"difficulty":"Moyen","imageSearch":"lamb potato stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"épaule d'agneau","plural":"épaules d'agneau","qty":1000,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":600,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":200,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer l'agneau en morceaux dans une cocotte.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute les oignons, la farine, les tomates, le thym et 50 cl d'eau.","timer":null},{"text":"Laisse mijoter 1 h.","timer":{"label":"Cuisson","min":60}},{"text":"Ajoute les pommes de terre et les carottes et laisse 30 min.","timer":{"label":"Cuisson","min":30}}],"variant":"Aux pommes de terre","change":"Avec des pommes de terre à la place des navets."},{"title":"Navarin d'agneau à la cocotte-minute","intro":"Le navarin en version rapide pour la semaine.","minutes":50,"calories":550,"difficulty":"Facile","imageSearch":"lamb stew pressure cooker","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"épaule d'agneau","plural":"épaules d'agneau","qty":1000,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":4,"unit":"","have":false},{"name":"navet","plural":"navets","qty":3,"unit":"","have":false},{"name":"petits pois surgelés","plural":"petits pois surgelés","qty":200,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":200,"unit":"g","have":false}],"steps":[{"text":"Fais dorer l'agneau dans la cocotte-minute avec les oignons.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute les tomates, les carottes, les navets et 30 cl d'eau.","timer":null},{"text":"Ferme et compte 25 min après le sifflement.","timer":{"label":"Cuisson","min":25}},{"text":"Ajoute les petits pois et laisse 5 min sans couvercle.","timer":{"label":"Cuisson","min":5}}],"variant":"Express","change":"Cuit à la cocotte-minute, en moins de temps."}]$r$::jsonb, 'claude')
