insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('veau marengo', 'Veau Marengo', array['saute de veau', 'marengo', 'saute de veau marengo']::text[], 'dish', $r$[{"title":"Sauté de veau Marengo","intro":"Le sauté de veau mijoté à la tomate et au vin blanc, avec des champignons.","minutes":105,"calories":450,"difficulty":"Facile","imageSearch":"veal marengo stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat français","serves":4,"items":[{"name":"sauté de veau","plural":"sauté de veau","qty":1000,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vin blanc","qty":20,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais dorer le veau en morceaux dans une cocotte huilée.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute les oignons, saupoudre de farine et remue.","timer":null},{"text":"Ajoute le vin, les tomates, le bouquet garni et 20 cl d'eau.","timer":null},{"text":"Laisse mijoter 1 h 15.","timer":{"label":"Cuisson","min":75}},{"text":"Ajoute les champignons émincés et laisse 15 min.","timer":{"label":"Cuisson","min":15}}],"variant":"La classique","change":""},{"title":"Poulet Marengo","intro":"La recette Marengo d'origine, au poulet.","minutes":60,"calories":420,"difficulty":"Facile","imageSearch":"chicken marengo","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":4,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vin blanc","qty":15,"unit":"cl","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false}],"steps":[{"text":"Fais dorer le poulet dans une cocotte.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute les oignons et l'ail, puis le vin et les tomates.","timer":null},{"text":"Laisse mijoter 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Ajoute les champignons et laisse 15 min.","timer":{"label":"Cuisson","min":15}}],"variant":"Au poulet","change":"Le poulet remplace le veau, plus rapide."},{"title":"Sauté de dinde Marengo","intro":"Un Marengo léger et économique, à la dinde.","minutes":55,"calories":350,"difficulty":"Facile","imageSearch":"turkey tomato stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sauté de dinde","plural":"sauté de dinde","qty":800,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Fais dorer la dinde dans une cocotte.","timer":{"label":"Cuisson","min":6}},{"text":"Ajoute les oignons, le vin et les tomates.","timer":null},{"text":"Laisse mijoter 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Ajoute les champignons et laisse 15 min.","timer":{"label":"Cuisson","min":15}}],"variant":"À la dinde","change":"Avec du sauté de dinde, plus léger."}]$r$::jsonb, 'claude')
