insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('jambalaya', 'Jambalaya', array['jambalaya poulet chorizo', 'riz cajun']::text[], 'dish', $r$[{"title":"Jambalaya","intro":"Le riz cajun de Louisiane au poulet, chorizo et crevettes, cuit dans une seule cocotte.","minutes":50,"calories":580,"difficulty":"Moyen","imageSearch":"jambalaya","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette de Louisiane","serves":4,"items":[{"name":"riz","plural":"riz","qty":300,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"chorizo","plural":"chorizos","qty":100,"unit":"g","have":false},{"name":"crevette décortiquée","plural":"crevettes décortiquées","qty":200,"unit":"g","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"c. à c.","have":false},{"name":"bouillon de volaille","plural":"bouillon de volaille","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet en dés et le chorizo en rondelles dans une cocotte.","timer":{"label":"Cuisson","min":6}},{"text":"Ajoute l'oignon et le poivron en dés, et le paprika.","timer":null},{"text":"Ajoute le riz, les tomates, le bouillon et 50 cl d'eau.","timer":null},{"text":"Couvre et laisse cuire 20 min à feu doux.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les crevettes et laisse 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"La classique","change":""},{"title":"Jambalaya aux crevettes","intro":"Le jambalaya de la mer, aux crevettes.","minutes":40,"calories":450,"difficulty":"Moyen","imageSearch":"shrimp jambalaya","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz","plural":"riz","qty":30