 d'eau.","timer":null},{"text":"Couvre et laisse cuire 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les haricots rouges égouttés et laisse 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"Végétarien","change":"Avec des haricots rouges à la place de la viande."}]$r$::jsonb, 'claude')
