insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('frite maison', 'Frites maison', array['frite', 'frite au four']::text[], 'dish', $r$[{"title":"Frites maison","intro":"Des frites croustillantes, cuites en deux fois comme au restaurant.","minutes":50,"calories":380,"difficulty":"Moyen","imageSearch":"homemade french fries","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Épluche les pommes de terre et coupe-les en bâtonnets de 1 cm.","timer":null},{"text":"Rince-les et sèche-les bien dans un torchon.","timer":null},{"text":"Fais-les cuire 6 min dans l'huile à 160 °C, puis égoutte-les.","timer":{"label":"Friture","min":6}},{"text":"Repasse-les 3 min dans l'huile à 180 °C pour les dorer.","timer":{"label":"Friture","min":3}},{"text":"Égoutte sur du papier absorbant et sale.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Frites au four","intro":"Des frites plus légères, croustillantes, sans friteuse.","minutes":45,"calories":220,"difficulty":"Facile","imageSearch":"oven baked fries","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 220 °C.","timer":null},{"text":"Coupe les pommes de terre en bâtonnets, rince-les et sèche-les.","timer":null},{"text":"Mélange-les avec l'huile, le paprika et le sel, et étale-les sur une plaque.","timer":null},{"text":"Enfourne 35 min en les retournant à mi-cuisson.","timer":{"label":"Four","min":35}}],"kids":true,"variant":"Sans friture","change":"Cuites au four avec un peu d'huile."},{"title":"Frites de patate douce","intro":"Des frites orange, sucrées et croustillantes.","minutes":40,"calories":230,"difficulty":"Facile","imageSearch":"sweet potato fries","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"patate douce","plural":"patates douces","qty":3,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à s.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 220 °C.","timer":null},{"text":"Coupe les patates douces en bâtonnets et enrobe-les de fécule, d'huile et de paprika.","timer":null},{"text":"Étale-les sans qu'elles se touchent sur une plaque.","timer":null},{"text":"Enfourne 30 min en les retournant à mi-cuisson.","timer":{"label":"Four","min":30}}],"kids":true,"variant":"Patate douce","change":"Avec des patates douces, au four."}]$r$::jsonb, 'claude')
