insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pomme de terre sautee', 'Pommes de terre sautées', array['patate sautee', 'pomme sautee', 'pomme de terre sarladaise', 'sarladaise']::text[], 'dish', $r$[{"title":"Pommes de terre sautées","intro":"Des pommes de terre dorées à la poêle, avec de l'ail et du persil.","minutes":35,"calories":280,"difficulty":"Facile","imageSearch":"pan fried potatoes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"huile","plural":"huile","qty":3,"unit":"c. à s.","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Épluche les pommes de terre et coupe-les en dés.","timer":null},{"text":"Fais-les dorer 25 min dans l'huile et le beurre à feu moyen, en remuant souvent.","timer":{"label":"Poêle","min":25}},{"text":"Ajoute l'ail et le persil hachés en fin de cuisson.","timer":null},{"text":"Sale et poivre.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Pommes de terre sarladaises","intro":"Les pommes de terre du Périgord, à la graisse de canard et à l'ail.","minutes":40,"calories":380,"difficulty":"Facile","imageSearch":"sarladaise potatoes duck fat","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité du Périgord","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"graisse de canard","plural":"graisse de canard","qty":3,"unit":"c. à s.","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Épluche les pommes de terre et coupe-les en rondelles.","timer":null},{"text":"Fais-les dorer 30 min dans la graisse de canard, en les retournant.","timer":{"label":"Poêle","min":30}},{"text":"Ajoute l'ail et le persil hachés 5 min avant la fin.","timer":null},{"text":"Sale et poivre.","timer":null}],"kids":true,"variant":"Sarladaises","change":"Sautées dans la graisse de canard."},{"title":"Pommes de terre sautées aux lardons","intro":"Une poêlée de pommes de terre complète, aux lardons.","minutes":35,"calories":420,"difficulty":"Facile","imageSearch":"potatoes bacon onions skillet","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"lardon","plural":"lardons","qty":200,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"huile","plural":"huile","qty":2,"unit":"c. à s.","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les pommes de terre en dés.","timer":null},{"text":"Fais-les dorer 20 min dans l'huile.","timer":{"label":"Poêle","min":20}},{"text":"Ajoute les lardons et les oignons émincés et laisse 10 min.","timer":{"label":"Poêle","min":10}},{"text":"Parsème de persil.","timer":null}],"kids":true,"variant":"Aux lardons","change":"Avec des lardons et des oignons."}]$r$::jsonb, 'claude')
