insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pomme de terre au four', 'Pommes de terre au four', array['patate au four', 'pomme de terre rissolee au four', 'smashed potatoe']::text[], 'dish', $r$[{"title":"Pommes de terre rôties au four","intro":"Des quartiers de pommes de terre rôtis au thym et à l'ail, croustillants dehors.","minutes":50,"calories":250,"difficulty":"Facile","imageSearch":"roasted potato wedges","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"ail","plural":"ail","qty":4,"unit":"gousse","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 210 °C.","timer":null},{"text":"Coupe les pommes de terre en quartiers sans les éplucher.","timer":null},{"text":"Mélange-les avec l'huile, le thym, l'ail en chemise et le sel.","timer":null},{"text":"Enfourne 40 min en remuant à mi-cuisson.","timer":{"label":"Four","min":40}}],"kids":true,"variant":"La classique","change":""},{"title":"Smashed potatoes","intro":"Les pommes de terre écrasées et croustillantes, très à la mode.","minutes":55,"calories":260,"difficulty":"Facile","imageSearch":"smashed potatoes","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre grenaille","plural":"pommes de terre grenailles","qty":800,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"parmesan","plural":"parmesans","qty":30,"unit":"g","have":false},{"name":"ail en poudre","plural":"ail en poudre","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min à l'eau salée.","timer":{"label":"Cuisson","min":20}},{"text":"Préchauffe le four à 220 °C. Pose-les sur une plaque et écrase-les avec un verre.","timer":null},{"text":"Arrose d'huile, saupoudre d'ail et de parmesan.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"kids":true,"variant":"Écrasées","change":"Des grenailles cuites, écrasées puis rôties."},{"title":"Pommes de terre en robe des champs","intro":"Des pommes de terre au four avec une crème à la ciboulette.","minutes":70,"calories":300,"difficulty":"Facile","imageSearch":"baked potato sour cream chives","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Pique les pommes de terre et enveloppe-les de papier aluminium.","timer":null},{"text":"Enfourne 1 h.","timer":{"label":"Four","min":60}},{"text":"Mélange la crème avec la ciboulette, le sel et le poivre.","timer":null},{"text":"Fends les pommes de terre et garnis-les de crème.","timer":null}],"kids":true,"variant":"Farcies","change":"Cuites entières, garnies de crème à la ciboulette."}]$r$::jsonb, 'claude')
