insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('aligot', 'Aligot', array['aligot aubrac', 'aligot saucisse', 'truffade']::text[], 'dish', $r$[{"title":"Aligot","intro":"La purée filante de l'Aubrac, à la tomme fraîche et à l'ail.","minutes":45,"calories":580,"difficulty":"Moyen","imageSearch":"aligot cheesy mashed potatoes","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spécialité de l'Aubrac","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"tomme fraîche","plural":"tomme fraîche","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":50,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 25 min à l'eau salée.","timer":{"label":"Cuisson","min":25}},{"text":"Écrase-les en purée avec le beurre, la crème et l'ail écrasé, sur feu doux.","timer":null},{"text":"Ajoute la tomme en lamelles petit à petit.","timer":null},{"text":"Remue énergiquement en soulevant jusqu'à ce que l'aligot file.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Aligot et saucisse","intro":"L'aligot en plat complet, avec ses saucisses.","minutes":50,"calories":820,"difficulty":"Moyen","imageSearch":"aligot sausage","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité de l'Aubrac","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"tomme fraîche","plural":"tomme fraîche","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":50,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"saucisse de Toulouse","plural":"saucisses de Toulouse","qty":4,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Pendant ce temps, fais griller les saucisses 15 min à la poêle.","timer":{"label":"Poêle","min":15}},{"text":"Écrase les pommes de terre avec le beurre, la crème et l'ail sur feu doux.","timer":null},{"text":"Ajoute la tomme et remue jusqu'à ce que ça file.","timer":null}],"kids":true,"variant":"Avec saucisse","change":"Servi avec des saucisses de Toulouse grillées."},{"title":"Truffade","intro":"Le plat auvergnat : pommes de terre sautées et tomme fondue.","minutes":45,"calories":620,"difficulty":"Facile","imageSearch":"truffade potatoes cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité auvergnate","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"tomme fraîche","plural":"tomme fraîche","qty":300,"unit":"g","have":false},{"name":"lardon","plural":"lardons","qty":100,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les pommes de terre en fines rondelles.","timer":null},{"text":"Fais-les dorer 25 min avec les lardons.","timer":{"label":"Poêle","min":25}},{"text":"Ajoute l'ail haché et la tomme en lamelles.","timer":null},{"text":"Mélange jusqu'à ce que le fromage fonde et parsème de persil.","timer":null}],"variant":"Truffade","change":"Des pommes de terre sautées à la tomme, sans purée."}]$r$::jsonb, 'claude')
