insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gratin de pate', 'Gratin de pâtes', array['pate gratinee', 'gratin de macaroni', 'macaroni au fromage', 'mac and cheese']::text[], 'dish', $r$[{"title":"Gratin de pâtes au jambon","intro":"Des pâtes en béchamel avec du jambon, gratinées à l'emmental.","minutes":45,"calories":580,"difficulty":"Facile","imageSearch":"pasta bake ham cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes courtes","plural":"pâtes courtes","qty":400,"unit":"g","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"muscade","plural":"muscade","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais cuire les pâtes 2 min de moins que le paquet.","timer":{"label":"Cuisson","min":8}},{"text":"Fais fondre le beurre, ajoute la farine, puis le lait en fouettant jusqu'à ce que ça épaississe.","timer":null},{"text":"Sale, poivre et ajoute un peu de muscade.","timer":null},{"text":"Mélange les pâtes, le jambon en dés et la béchamel dans un plat.","timer":null},{"text":"Couvre d'emmental et enfourne 20 min.","timer":{"label":"Four","min":20}}],"kids":true,"variant":"La classique","change":""},{"title":"Mac and cheese","intro":"Le plat américain ultra fondant au cheddar.","minutes":40,"calories":620,"difficulty":"Facile","imageSearch":"mac and cheese","veg":true,"oven":true,"cold":false,"missing":"","origin":"Recette américaine","serves":4,"items":[{"name":"macaronis","plural":"macaronis","qty":400,"unit":"g","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":200,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"chapelure","plural":"chapelure","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais cuire les macaronis.","timer":{"label":"Cuisson","min":8}},{"text":"Fais une béchamel avec le beurre, la farine et le lait.","timer":null},{"text":"Ajoute les trois quarts du cheddar et remue jusqu'à ce qu'il fonde.","timer":null},{"text":"Mélange avec les pâtes, verse dans un plat, couvre du reste de cheddar et de chapelure.","timer":null},{"text":"Enfourne 15 min.","timer":{"label":"Four","min":15}}],"kids":true,"variant":"Mac and cheese","change":"Des macaronis dans une sauce au cheddar."},{"title":"Gratin de pâtes aux légumes","intro":"Un gratin de pâtes végétarien, plein de légumes.","minutes":45,"calories":480,"difficulty":"Facile","imageSearch":"vegetable pasta bake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes courtes","plural":"pâtes courtes","qty":350,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais cuire les pâtes.","timer":{"label":"Cuisson","min":8}},{"text":"Fais revenir la courgette et le poivron en dés 8 min, puis ajoute les tomates.","timer":{"label":"Poêle","min":8}},{"text":"Mélange avec les pâtes dans un plat.","timer":null},{"text":"Couvre de mozzarella et d'emmental, et enfourne 20 min.","timer":{"label":"Four","min":20}}],"kids":true,"variant":"Végétarien","change":"Avec courgette, poivron et tomates."}]$r$::jsonb, 'claude')
